// tense-quiz-data.js — 时态专项练习题（初中阶段8种时态）
// 数据来源：外部链接时态练习内容整合

const TENSE_QUIZ_DATA = {
  t1: {
    icon: "📅",
    intro: "一般现在时（do / does）：表示经常性或习惯性的动作、客观事实、普遍真理，或按计划将发生的事。",
    questions: [
      { q: "She ______ to school by bus every day.", options: ["go", "goes", "going", "went"], answer: 1, explain: "主语 She 是第三人称单数，一般现在时中动词要加 -es。go 以 o 结尾，加 -es 变为 goes。口诀：三单主语，动词加 s/es。" },
      { q: "The sun ______ in the east.", options: ["rise", "rises", "rose", "rising"], answer: 1, explain: "太阳从东方升起是客观事实，用一般现在时。The sun 是第三人称单数，动词 rise 加 -s 变为 rises。考点：客观真理永远用一般现在时。" },
      { q: "I ______ my teeth twice a day.", options: ["brush", "brushes", "brushing", "brushed"], answer: 0, explain: "I 是第一人称，一般现在时中动词用原形。twice a day（一天两次）表示习惯性动作。记忆：I/You/We/They + 动词原形，He/She/It + 动词加 s/es。" },
      { q: "They ______ football after school.", options: ["plays", "play", "playing", "played"], answer: 1, explain: "主语 They 是复数，一般现在时中动词用原形 play，不加 s。只有第三人称单数（he/she/it）才需要动词加 s/es。" },
      { q: "______ your father work in a hospital?", options: ["Do", "Does", "Is", "Are"], answer: 1, explain: "一般现在时的疑问句，主语 your father 是第三人称单数，用 Does 开头，后面动词恢复原形 work。公式：Does + 三单主语 + 动词原形？" },
      { q: "He doesn't ______ coffee.", options: ["drinks", "drink", "drinking", "drank"], answer: 1, explain: "否定句中用了 doesn't（does not），后面的动词必须恢复原形 drink。规则：does/doesn't 后面动词永远用原形。" },
      { q: "My father ______ to work by car every day.", options: ["go", "goes", "going", "went"], answer: 1, explain: "主语 My father 是第三人称单数，一般现在时中动词要变化。go 以 o 结尾，加 -es 变为 goes。口诀：三单主语，动词加 s/es；go 和 do 加 -es。" },
      { q: "The earth ______ around the sun.", options: ["go", "goes", "going", "went"], answer: 1, explain: "地球绕太阳转是客观事实，永远用一般现在时。The earth 是第三人称单数，go 加 -es 变为 goes。核心考点：客观事实/科学真理 → 一般现在时，不受主句时态影响。" },
      { q: "She ______ reading books in the evening.", options: ["like", "likes", "liking", "liked"], answer: 1, explain: "主语 She 是第三人称单数，一般现在时中动词要加 -s。like 以不发音的 e 结尾，直接加 -s 变为 likes。三单动词变化规则：一般加 -s，以 s/x/ch/sh/o 结尾加 -es。" },
      { q: "We ______ English class on Monday.", options: ["have", "has", "having", "had"], answer: 0, explain: "主语 We 是第一人称复数，一般现在时中动词用原形 have。只有第三人称单数（he/she/it/单数名词）才需要动词加 s/es。" },
      { q: "Water ______ at 100°C.", options: ["boil", "boils", "boiling", "boiled"], answer: 1, explain: "水在100°C沸腾是科学事实，永远用一般现在时。Water 是不可数名词，视为第三人称单数，boil 加 -s 变为 boils。科学事实和客观真理，无论上下文时态如何，都用一般现在时。" },
      { q: "My brother often ______ basketball after school.", options: ["play", "plays", "playing", "played"], answer: 1, explain: "often（经常）是频率副词，提示习惯性动作用一般现在时。My brother 是第三人称单数，play 加 -s 变为 plays。频率副词（often/usually/always/sometimes）→ 一般现在时的标志词。" },
      { q: "The train ______ at 8:00 a.m. every morning.", options: ["leave", "leaves", "leaving", "left"], answer: 1, explain: "火车时刻表是固定安排，用一般现在时表示将来。The train 是第三人称单数，leave 加 -s 变为 leaves。时刻表、日程安排等固定计划，可用一般现在时代替一般将来时。" },
      { q: "He ______ TV on weekdays.", options: ["don't watch", "doesn't watch", "isn't watch", "not watch"], answer: 1, explain: "主语 He 是第三人称单数，否定句用 doesn't（does not）+ 动词原形 watch。公式：三单主语 + doesn't + 动词原形。doesn't 后面动词必须恢复原形！" },
      { q: "______ your sister ______ homework every night?", options: ["Do;do", "Does;do", "Does;does", "Is;do"], answer: 1, explain: "一般现在时的一般疑问句，主语 your sister 是第三人称单数，用 Does 开头，后面动词恢复原形 do。公式：Does + 三单主语 + 动词原形？Do/Does 后面的动词永远用原形！" },
      { q: "How often ______ you ______ shopping?", options: ["do;go", "does;go", "do;goes", "are;go"], answer: 0, explain: "How often 提问频率，用一般现在时。主语 you 不是第三人称单数，用 do + 动词原形 go。特殊疑问句公式：疑问词 + do/does + 主语 + 动词原形。you 用 do，三单用 does。" },
      { q: "Miss Guo ______ us Chinese this term. She is a very good teacher.", options: ["teach", "teaches", "teaching", "to teach"], answer: 1, explain: "Miss Guo 是第三人称单数，this term（本学期）表示当前状态，用一般现在时。teach 以 ch 结尾，加 -es 变为 teaches。变化规则：以 s/x/sh/ch/o 结尾的动词加 -es。" },
      { q: "She often ______ with us after class.", options: ["talk", "talks", "talking", "to talk"], answer: 1, explain: "She 是第三人称单数，often 表示经常性动作，用一般现在时。talk 直接加 -s 变为 talks。频率副词 often/usually/always 常与一般现在时连用。" },
      { q: "Many of us like ______ with her.", options: ["talk", "to talk", "talking", "talks"], answer: 2, explain: "like doing sth. 是固定搭配，表示「喜欢做某事」。like 后面接动词-ing 形式。like talking with her（喜欢和她聊天）。注意：like 后也可接 to do，但初中阶段常考 like doing。" },
      { q: "— Where ______ their father work? — He works on a farm.", options: ["do", "does", "is", "are"], answer: 1, explain: "their father 是第三人称单数，疑问句用 does 开头，后面动词恢复原形 work。公式：Does + 三单主语 + 动词原形？do/does 后面的动词永远用原形！" },
      { q: "— Where does their father work? — He ______ on a farm.", options: ["work", "works", "working", "to work"], answer: 1, explain: "He 是第三人称单数，一般现在时中动词要加 -s。work 直接加 -s 变为 works。注意：疑问句中用 does + 原形，但陈述句中三单主语要加 -s。" },
      { q: "— What time ______ the shop close? — It closes at nine o'clock in the evening.", options: ["do", "does", "is", "are"], answer: 1, explain: "the shop 是第三人称单数，疑问句用 does 开头，后面动词恢复原形 close。What time 提问时间，用 does + 三单主语 + 动词原形。" },
      { q: "— What time does the shop close? — It ______ at nine o'clock in the evening.", options: ["close", "closes", "closing", "to close"], answer: 1, explain: "It（指代 the shop）是第三人称单数，close 以 e 结尾，直接加 -s 变为 closes。注意：close 的三单形式只加 -s，不加 -es。" },
      { q: "He ______ to school by bus every day.", options: ["go", "goes", "going", "to go"], answer: 1, explain: "He 是第三人称单数，every day 表示每天的习惯性动作，用一般现在时。go 以 o 结尾，加 -es 变为 goes。go/do/echo 等以 o 结尾的动词三单加 -es。" },
      { q: "Tom can not walk fast because he ______ a heavy box.", options: ["carry", "carries", "carrying", "to carry"], answer: 1, explain: "he 是第三人称单数，carry 以辅音字母+y结尾，变 y 为 i 加 -es 变为 carries。can not 后跟动词原形 walk，但 because 从句中用一般现在时表原因。" },
      { q: "She often ______ English in the evening.", options: ["read", "reads", "reading", "to read"], answer: 1, explain: "She 是第三人称单数，often 表示经常性动作。read 直接加 -s 变为 reads。注意：read 的原形和过去式拼写相同，但读音不同（原形 /riːd/，过去式 /red/），三单 reads 读作 /riːdz/。" },
      { q: "She ______ to school at eight o'clock.", options: ["go", "goes", "going", "to go"], answer: 1, explain: "She 是第三人称单数，at eight o'clock 表示日常时间安排，用一般现在时。go 以 o 结尾，加 -es 变为 goes。日常作息时间用一般现在时。" },
      { q: "He usually ______ up at 17:00.", options: ["get", "gets", "getting", "to get"], answer: 1, explain: "He 是第三人称单数，usually 表示习惯性动作。get 直接加 -s 变为 gets。频率副词 usually 常放在实义动词前，be动词后。" },
      { q: "She ______ in Beijing.", options: ["live", "lives", "living", "to live"], answer: 1, explain: "She 是第三人称单数，live 以 e 结尾，直接加 -s 变为 lives。表示居住地用一般现在时，live 表示长期居住的状态。" }
    ]
  },
  t2: {
    icon: "⏮️",
    intro: "一般过去时：表示过去发生的动作或状态。结构：主语 + 动词过去式。常与 yesterday, last week, ago 等连用。",
    questions: [
      { q: "I ______ a movie yesterday evening.", options: ["watch", "watched", "watching", "watches"], answer: 1, explain: "yesterday evening（昨天晚上）是过去时间，动词用过去式。watch 是规则动词，直接加 -ed 变为 watched。规则动词过去式 = 动词原形 + ed。" },
      { q: "She ______ to Beijing last summer.", options: ["go", "goes", "went", "gone"], answer: 2, explain: "go 是不规则动词，过去式为 went。last summer（去年夏天）是明确的过去时间。常考不规则动词：go→went, come→came, see→saw, eat→ate。" },
      { q: "They ______ the classroom yesterday.", options: ["don't clean", "didn't clean", "didn't cleaned", "doesn't clean"], answer: 1, explain: "一般过去时的否定用 didn't + 动词原形。didn't 后面动词必须恢复原形 clean，不能再用过去式。公式：didn't + 动词原形。不管主语是谁，都用 didn't！" },
      { q: "______ you at home last night?", options: ["Do", "Did", "Were", "Are"], answer: 2, explain: "这里的 at home 是状态（不是动作），用 be 动词的过去式。主语 you 用 were。有 be 动词（am/is/are → was/were）的句子，疑问句把 be 动词提前即可。" },
      { q: "He ______ born in 2010.", options: ["is", "was", "were", "are"], answer: 1, explain: "be born（出生）是过去的动作，要用过去式。主语 He 是第三人称单数，be 动词用 was。记住：出生一定是过去的事，用 was/were born。" },
      { q: "Tom ______ his homework and then went out.", options: ["finish", "finishes", "finished", "finishing"], answer: 2, explain: "and then went out 中的 went 是过去式，前面的动作也应该用过去式 finished，表示两个先后发生的过去动作。并列句中时态要保持一致。" },
      { q: "I ______ a new dictionary the day before yesterday.", options: ["buy", "bought", "buying", "buys"], answer: 1, explain: "the day before yesterday（前天）是明确的过去时间，用一般过去时。buy 是不规则动词，过去式为 bought。常考不规则动词：buy→bought, bring→brought, think→thought。" },
      { q: "— What day ______ it yesterday? — It was Friday.", options: ["is", "was", "were", "are"], answer: 1, explain: "yesterday（昨天）是过去时间，it 是第三人称单数，be 动词过去式用 was。疑问句把 be 动词提前：Was it...? 口诀：am/is→was，are→were。" },
      { q: "— What day was it yesterday? — It ______ Friday.", options: ["is", "was", "were", "are"], answer: 1, explain: "答句与问句时态一致，都用一般过去时。It 是第三人称单数，be 动词用 was。It was Friday（那天是星期五）。" },
      { q: "He ______ here half an hour ago.", options: ["is", "was", "were", "be"], answer: 1, explain: "half an hour ago（半小时前）是过去时间，He 是第三人称单数，be 动词用 was。ago 是一般过去时的标志词：...ago → 用过去时。" },
      { q: "We often ______ games last term.", options: ["play", "played", "playing", "plays"], answer: 1, explain: "last term（上学期）是过去时间，用一般过去时。play 是规则动词，加 -ed 变为 played。注意：虽然有 often，但 last term 决定了用过去时，often 只是表示在那个时期内的频率。" },
      { q: "She ______ me a book a moment ago.", options: ["give", "gave", "giving", "gives"], answer: 1, explain: "a moment ago（刚才）是过去时间，give 是不规则动词，过去式为 gave。常考不规则动词：give→gave, take→took, make→made。" },
      { q: "The girl ______ up very early this morning.", options: ["get", "got", "getting", "gets"], answer: 1, explain: "this morning 在此语境指今天早上（已过去），用一般过去时。get 是不规则动词，过去式为 got。get up（起床）的过去式 = got up。" },
      { q: "They ______ photos near the river an hour ago.", options: ["take", "took", "taking", "takes"], answer: 1, explain: "an hour ago（一小时前）是过去时间，take 是不规则动词，过去式为 took。take photos（拍照）的过去式 = took photos。" },
      { q: "He ______ TV yesterday evening.", options: ["doesn't watch", "didn't watch", "didn't watched", "not watched"], answer: 1, explain: "yesterday evening（昨天晚上）是过去时间，否定句用 didn't + 动词原形 watch。注意：didn't 后面动词必须恢复原形，不能用 watched！公式：didn't + 动词原形。" },
      { q: "— Why ______ the boy late for school? — Because he was ill.", options: ["is", "was", "were", "did"], answer: 1, explain: "答句 was ill 表明是过去的事，问句也用过去时。the boy 是单数，be 动词用 was。疑问句把 be 动词提前：Why was the boy...?" },
      { q: "— Why was the boy late for school? — Because he ______ ill.", options: ["is", "was", "were", "did"], answer: 1, explain: "与问句时态一致，用一般过去时。he 是第三人称单数，be 动词用 was。Because 引导原因状语从句，时态与主句保持一致。" },
      { q: "Mr. Green ______ to visit me last night.", options: ["come", "came", "coming", "comes"], answer: 1, explain: "last night（昨晚）是过去时间，come 是不规则动词，过去式为 came。常考不规则动词：come→came, run→ran, become→became。" },
      { q: "The teacher ______ to our idea yesterday.", options: ["agree", "agreed", "agreeing", "agrees"], answer: 1, explain: "yesterday（昨天）是过去时间，agree 是规则动词，加 -d 变为 agreed。注意：agree 以 e 结尾，只加 -d，不加 -ed。规则：以 e 结尾的动词只加 -d。" },
      { q: "They ______ him work twelve hours a day last year.", options: ["make", "made", "making", "makes"], answer: 1, explain: "last year（去年）是过去时间，make 是不规则动词，过去式为 made。make sb. do sth.（让某人做某事）的过去式 = made sb. do sth.，注意 make 后的动词用原形。" },
      { q: "I ______ him in the library two days ago.", options: ["see", "saw", "seeing", "sees"], answer: 1, explain: "two days ago（两天前）是过去时间，see 是不规则动词，过去式为 saw。常考不规则动词：see→saw, buy→bought, teach→taught。" },
      { q: "She ______ her address on the blackboard ten minutes ago.", options: ["write", "wrote", "writing", "writes"], answer: 1, explain: "ten minutes ago（十分钟前）是过去时间，write 是不规则动词，过去式为 wrote。常考不规则动词：write→wrote, ride→rode, drive→drove。" },
      { q: "— What did your father do when he was in England? — He ______ in a car factory.", options: ["work", "worked", "is working", "will work"], answer: 1, explain: "when he was in England（当他在英国时）是过去时间，答句用一般过去时 worked。问句用 did 提问，答句动词用过去式。注意：did 提问时答句不能用 did+原形，要用动词过去式。" },
      { q: "— ______ he ______ at this school last term? — Yes, I think so.", options: ["Did;study", "Does;study", "Was;study", "Did;studied"], answer: 0, explain: "last term（上学期）是过去时间，一般疑问句用 Did + 主语 + 动词原形 study。注意：Did 后面动词必须用原形，不能用 studied！选项 D 是常见错误。" },
      { q: "— Who cleaned the blackboard yesterday, Dick? — John ______.", options: ["cleaned", "does", "did", "is"], answer: 2, explain: "问句已用 cleaned，答句为避免重复用 did 代替 cleaned。John did = John cleaned the blackboard。do/does/did 可作代动词，代替前面提到的动作。" },
      { q: "There ______ a lot of people at the street corner when the accident happened.", options: ["was", "were", "have been", "had"], answer: 1, explain: "a lot of people 是复数，be 动词用 were。when the accident happened（事故发生时）是过去时间。There be 句型：单数用 was，复数用 were。people 是集体名词，视为复数。" },
      { q: "He turned off the lights and then ______.", options: ["leaves", "left", "will leave", "is leaving"], answer: 1, explain: "turned off 是过去式，and then 连接两个先后发生的动作，第二个动词也要用过去式 left。并列句中时态保持一致：turned ... and ... left。" },
      { q: "— Hi, Kate. You look tired. What's the matter? — I ______ well last night.", options: ["didn't sleep", "don't sleep", "haven't slept", "won't sleep"], answer: 0, explain: "last night（昨晚）是过去时间，否定句用 didn't + 动词原形 sleep。didn't sleep well（没睡好）。注意：last night 决定用过去时，不能用现在完成时。" },
      { q: "Jenny went into the room, took off his coat and ______ down on a sofa.", options: ["would sit", "was sitting", "sat", "had sat"], answer: 2, explain: "went, took off 是过去式，and 连接三个连续动作，最后用 sat（sit 的过去式）。并列连续动作时态一致：went → took off → sat。不规则动词：sit→sat。" },
      { q: "Everyone ______ there when the meeting began.", options: ["was", "is", "are", "were"], answer: 0, explain: "when the meeting began（会议开始时）是过去时间。everyone 是不定代词，视为第三人称单数，be 动词用 was。不定代词（everyone/everybody/someone/anyone/nobody）都视为单数。" }
    ]
  },
  t3: {
    icon: "⏭️",
    intro: "一般将来时：表示将来要发生的动作或状态。结构：主语 + will/shall + 动词原形，或 be going to + 动词原形。",
    questions: [
      { q: "I ______ you tomorrow morning.", options: ["call", "will call", "calling", "called"], answer: 1, explain: "tomorrow morning（明天早上）是将来时间，用 will + 动词原形。一般将来时公式：will + 动词原形，will 没有人称变化。" },
      { q: "Look at the clouds! It ______ rain.", options: ["will", "is going to", "going to", "shall"], answer: 1, explain: "Look at the clouds! 表示有迹象表明即将下雨，用 be going to 表示根据迹象推测将要发生的事。区别：will 偏向主观意愿，be going to 偏向计划或迹象。" },
      { q: "There ______ a sports meeting next week.", options: ["is", "will be", "will have", "has"], answer: 1, explain: "There be 句型表示「将有」，将来时用 There will be。next week 是将来时间。记住：There will be + 名词，不用 There will have。" },
      { q: "We ______ to the park if it doesn't rain.", options: ["go", "will go", "went", "going"], answer: 1, explain: "if 引导的条件状语从句中，从句用一般现在时（doesn't rain），主句用一般将来时（will go）。中考高频考点：主将从现——主句将来时，从句现在时。" },
      { q: "She ______ a doctor when she grows up.", options: ["is", "was", "is going to be", "being"], answer: 2, explain: "when she grows up（当她长大后）表示将来的计划，用 be going to。is going to be a doctor。表示职业梦想常用 be going to be。" },
      { q: "I promise I ______ late again.", options: ["am not", "won't be", "wasn't", "don't be"], answer: 1, explain: "won't 是 will not 的缩写。promise（承诺）是关于将来的，用将来时的否定 won't be。will not = won't，否定直接加在 will 后面。" },
      { q: "There ______ a meeting tomorrow afternoon.", options: ["will be going to", "will going to be", "is going to be", "will go to be"], answer: 2, explain: "tomorrow afternoon 是将来时间，There be 句型用 is going to be。There 不能与 have 连用。be going to be 表示按计划将要发生。注意：will be going to 结构错误，will 后接原形 be。" },
      { q: "Charlie ______ here next month.", options: ["isn't working", "doesn't working", "isn't going to working", "won't work"], answer: 3, explain: "next month 是将来时间，用将来时否定 won't work。will not = won't + 动词原形。选项C错误：be going to 后接动词原形 work，不接 working。" },
      { q: "He ______ very busy this week, he ______ free next week.", options: ["will be; is", "is; is", "will be; will be", "is; will be"], answer: 3, explain: "this week 是现在时间用 is，next week 是将来时间用 will be。时间标志词决定时态：this week → 现在时，next week → 将来时。" },
      { q: "There ______ a dolphin show in the zoo tomorrow evening.", options: ["was", "is going to have", "will have", "is going to be"], answer: 3, explain: "tomorrow evening 是将来时间，There be 句型用 is going to be。There 不能与 have 连用，只能说 There is going to be。这是中考高频考点。" },
      { q: "—______ you ______ free tomorrow? —No. I ______ free the day after tomorrow.", options: ["Are; going to; will", "Are; going to be; will", "Are; going to; will be", "Are; going to be; will be"], answer: 3, explain: "第一空问明天是否有空，用 Are you going to be；第二空回答后天才有空，用 will be。be going to be 和 will be 都表示将来，但疑问句结构为 Are + 主语 + going to be。" },
      { q: "Mother ______ me a nice present on my next birthday.", options: ["will gives", "will give", "gives", "give"], answer: 1, explain: "on my next birthday 是将来时间，用 will + 动词原形 give。will 后面动词永远用原形，不加 s。选项A错误：will + gives 结构错误。" },
      { q: "—Shall I buy a cup of tea for you? —________. (不，不要。)", options: ["No, you won't.", "No, you aren't.", "No, please don't.", "No, please."], answer: 2, explain: "Shall I...? 表示征求意见，否定回答用 No, please don't.（不，请不要买）。won't 用于回答 will 的疑问句，不是 shall 的否定回答。" },
      { q: "—Where is the morning paper? —I ______ it for you at once.", options: ["get", "am getting", "to get", "will get"], answer: 3, explain: "at once（马上）表示即时决定，用 will get。表示即时的决定/承诺用 will，不用 be going to。will + 动词原形 get。" },
      { q: "________ a concert next Saturday?", options: ["There will be", "Will there be", "There can be", "There are"], answer: 1, explain: "这是 There be 句型的一般疑问句，next Saturday 是将来时间，用 Will there be...? 结构：Will + there be + 名词？" },
      { q: "If they come, we ______ a meeting.", options: ["have", "will have", "had", "would have"], answer: 1, explain: "if 引导的条件状语从句中，从句用一般现在时（come），主句用一般将来时（will have）。主将从现原则：主句将来时，从句现在时。" },
      { q: "He ______ her a beautiful hat on her next birthday.", options: ["gives", "gave", "will give", "is going to giving"], answer: 2, explain: "on her next birthday 是将来时间，用 will + 动词原形 give。will 后面动词永远用原形。选项D错误：be going to 后接动词原形 give，不接 giving。" },
      { q: "He ______ to us as soon as he gets there.", options: ["writes", "has written", "will write", "wrote"], answer: 2, explain: "as soon as 引导时间状语从句，主将从现：主句用 will write，从句用一般现在时 gets。as soon as = 一…就…，将来时常见标志。will + 动词原形 write。" },
      { q: "He ______ in three days.", options: ["coming back", "came back", "will come back", "is going to coming back"], answer: 2, explain: "in three days（三天后）是将来时间，用 will come back。will + 动词原形。选项D错误：be going to 后接动词原形 come，不接 coming。选项A缺少 be 动词。" },
      { q: "If it ______ tomorrow, we'll go roller-skating.", options: ["isn't rain", "won't rain", "doesn't rain", "doesn't fine"], answer: 2, explain: "if 引导的条件状语从句中，主句用将来时（we'll go），从句用一般现在时。rain 是动词，否定用 doesn't rain。主将从现原则。选项A错误：rain 是动词不是形容词，否定用 doesn't。" },
      { q: "—Will his parents go to see the Terra Cotta Warriors tomorrow? —No, ________.", options: ["they willn't.", "they won't.", "they aren't.", "they don't."], answer: 1, explain: "Will...? 的否定回答用 No, they won't.。will not = won't，没有 willn't 这个形式。aren't 用于 be 动词疑问句，don't 用于一般现在时疑问句。" },
      { q: "Who ______ we ______ swimming with tomorrow afternoon?", options: ["will; go", "do; go", "will; going", "shall; go"], answer: 0, explain: "tomorrow afternoon 是将来时间，用 will go。疑问词 Who 放句首，后面用 will + 主语 + 动词原形。will 后面动词用原形 go，不接 going。" },
      { q: "We ______ the work this way next time.", options: ["do", "will do", "going to do", "will doing"], answer: 1, explain: "next time 是将来时间，用 will + 动词原形 do。will 后面动词永远用原形，不接 doing。选项C缺少 be 动词（应为 are going to do）。" },
      { q: "Tomorrow he ______ a kite in the open air first, and then ______ boating in the park.", options: ["will fly; will go", "will fly; goes", "is going to fly; will goes", "flies; will go"], answer: 0, explain: "Tomorrow 是将来时间，两个动作都用将来时 will fly 和 will go。and 连接两个并列的将来动作，时态一致。will 后面动词用原形。选项C错误：will goes 结构错误。" },
      { q: "The day after tomorrow they ______ a volleyball match.", options: ["will watching", "watches", "is watching", "are going to watch"], answer: 3, explain: "The day after tomorrow 是将来时间，they 是复数用 are going to watch。be going to + 动词原形。选项A错误：will + 原形不是 watching。选项B/C时态错误。" },
      { q: "There ______ a birthday party this Sunday.", options: ["shall be", "will be", "shall going to be", "will going to be"], answer: 1, explain: "this Sunday 是将来时间，There be 句型用 There will be。shall 通常用于第一人称 I/we。选项C/D结构错误，will/shall 后面直接接动词原形 be。" },
      { q: "They ______ an English evening next Sunday.", options: ["are having", "are going to have", "will having", "is going to have"], answer: 1, explain: "next Sunday 是将来时间，they 是复数用 are going to have。be going to + 动词原形。选项A是现在进行时，选项C错误（will + 原形不是 having），选项D主谓不一致（they→are）。" },
      { q: "________ you ______ free next Sunday?", options: ["Will; are", "Will; be", "Do; be", "Are; be"], answer: 1, explain: "next Sunday 是将来时间，用 Will you be...? Will + 主语 + 动词原形。be 动词的将来时是 will be，不是 will are。" },
      { q: "He ______ there at ten tomorrow morning.", options: ["will", "is", "will be", "be"], answer: 2, explain: "tomorrow morning 是将来时间，用 will be。will + be 动词原形。「在那里」表示状态，用 be 动词。选项A缺少 be 动词，选项B是现在时。" },
      { q: "________ your brother ______ a magazine from the library?", options: ["Are; going to borrow", "Is; going to borrow", "Will; borrows", "Are; going to borrows"], answer: 1, explain: "your brother 是第三人称单数，用 Is...going to borrow。be going to + 动词原形。选项A主谓不一致（brother→is），选项C will 后接原形不接 borrows。" },
      { q: "—Shall I come again tomorrow afternoon? —________. (好的)", options: ["Yes, please", "Yes, you will.", "No, please.", "No, you won't."], answer: 0, explain: "Shall I...? 表示征求意见，肯定回答用 Yes, please.（好的，请来吧）。表示同意对方的提议。" },
      { q: "It ______ the year of the horse next year.", options: ["is going to be", "is going to", "will be", "will is"], answer: 2, explain: "next year 是将来时间，用 will be。will + be 动词原形。选项D错误：will 后面不接 is。选项B缺少 be 动词。" },
      { q: "________ open the window?", options: ["Will you please", "Please will you", "You please", "Do you"], answer: 0, explain: "Will you please + 动词原形? 是礼貌请求句型。Will you please open the window? = 请你打开窗户好吗？这是固定句型结构。" },
      { q: "—Let's go out to play football, shall we? —OK. I ______.", options: ["will coming", "be going to come", "come", "am coming"], answer: 3, explain: "用现在进行时表将来 am coming = 我这就来。选项A错误（will + 原形不是 coming），选项B缺少 be 动词。I am coming. 是口语中常用的「我这就来」表达。" },
      { q: "It ______ us a long time to learn English well.", options: ["takes", "will take", "spends", "will spend"], answer: 1, explain: "It takes sb. time to do sth. 是固定句型。学英语需要很长时间是将来事实，用 will take。take 的主语是 it（事情），spend 的主语是人。" },
      { q: "The train ______ at 11.", options: ["going to arrive", "will be arrive", "is going to", "is arriving"], answer: 3, explain: "火车时刻表可以用现在进行时表将来 is arriving = 将到达。火车、飞机等交通工具的时刻表常用现在进行时或一般现在时表将来。选项A/C缺少 be 动词，选项B结构错误。" },
      { q: "I ______ in a minute. I ______ all my work before I ______.", options: ["will leave; will finish; leave", "leave; finish; will leave", "will leave; will finish; will leave", "am leaving; finishing; leaving"], answer: 0, explain: "in a minute 是将来时间用 will leave；before 引导的时间状语从句用一般现在时代替将来时（主将从现），所以 leave 用一般现在时。before/after/if/until 等引导的从句中，用一般现在时代替将来时。" },
      { q: "—What ______ you ______ after you ______ here? —I ______ home and ______ a job.", options: ["will; do; leave; will return; get", "do; do; will leave; return; get", "will; do; will leave; will return; get", "are; doing; leave; return; getting"], answer: 0, explain: "after 引导的时间状语从句用一般现在时 leave（主将从现）。主句用 will do。回答也用 will return and get。after/before/if 等引导的从句中，用一般现在时代替将来时。" },
      { q: "I ______ tired. I ______ to bed early tonight.", options: ["am; will go", "will be; go", "am; am going to", "will be; will go"], answer: 0, explain: "第一空表示当前状态用 am；第二空 tonight 是将来时间，表示即时的决定用 will go。will 可以表示即时的决定和意图。" },
      { q: "Mary's birthday is next Monday, her mother ______ her a present.", options: ["gives", "gave", "will give", "is giving"], answer: 2, explain: "next Monday 是将来时间，用 will + 动词原形 give。will 后面动词永远用原形，不加 s。" },
      { q: "It is very cold these days. It ______ soon.", options: ["will snow", "is going to snow", "snows", "snowed"], answer: 1, explain: "It is very cold these days 提供了天气迹象，用 be going to snow 表示根据迹象推测将要发生的事。区别：有迹象用 be going to，无迹象主观决定用 will。" },
      { q: "—______ you ______ here this Saturday? —No. I ______ my teacher.", options: ["Will; be; will visit", "Are; going to be; visit", "Will; be; am visiting", "Are; being; will visit"], answer: 0, explain: "this Saturday 是将来时间，用 Will you be...? 回答用 will visit。will + 动词原形。" },
      { q: "—______ I ______ you a copy of today's newspaper? —Thank you.", options: ["Will; get", "Shall; get", "Do; get", "Am; getting"], answer: 1, explain: "Shall I...? 用于征求意见，表示「我给你拿一份今天的报纸好吗？」。Shall I/we + 动词原形 是征求意见的固定句型。" },
      { q: "I am afraid there ______ a meeting this afternoon. I can't join you.", options: ["will be", "is going to have", "will have", "is"], answer: 0, explain: "this afternoon 是将来时间，There be 句型用 There will be。There 不能与 have 连用。I am afraid 后面用将来时表示对将来的推测。" },
      { q: "Mike ______ this until he ______ it with his own eyes.", options: ["doesn't believe; sees", "won't believe; sees", "won't believe; will see", "doesn't believe; will see"], answer: 1, explain: "until 引导的时间状语从句中，主句用将来时 won't believe，从句用一般现在时 sees（主将从现）。not...until... = 直到…才…。until/before 引导的从句用一般现在时代替将来时。" },
      { q: "Most of us don't think their team ______.", options: ["will win", "wins", "won", "is winning"], answer: 0, explain: "think 后面的宾语从句表示对将来的预测，用 will win。will + 动词原形。Most of us don't think their team will win. = 我们大多数人认为他们队赢不了。" }
    ]
  },
  t4: {
    icon: "🔄",
    intro: "过去将来时：表示从过去某时间看将来要发生的动作。结构：主语 + would + 动词原形，或 was/were going to + 动词原形。含中考真题集锦35道，涵盖过去将来时与过去进行时中考精选题。",
    questions: [
      { q: "He said he ______ come to the party.", options: ["will", "would", "is going to", "shall"], answer: 1, explain: "He said 是过去时，后面的宾语从句中「将要来」需用过去将来时 would。规则：主句过去时 → 从句 will 要变 would。" },
      { q: "She told me she ______ visit her grandma the next day.", options: ["will", "would", "is going to", "was"], answer: 1, explain: "She told me 是过去时，the next day 对应直接引语中的 tomorrow，从句用过去将来时 would visit。时态呼应：主句过去时，从句的将来要用 would。" },
      { q: "They didn't know what ______ next.", options: ["happen", "will happen", "would happen", "happened"], answer: 2, explain: "主句 didn't know 是过去时，从句「将要发生什么」需用 would happen。宾语从句中，主过从过：主句用过去时，从句也要用相应的过去时态。" },
      { q: "I thought you ______ with me.", options: ["come", "will come", "would come", "are coming"], answer: 2, explain: "I thought 是过去时，后面的从句要用过去将来时 would come，表示「我当时以为你会来」。thought/believed/hoped 等过去式后面的 will 要变 would。" },
      { q: "He was about to leave when the phone ______.", options: ["ring", "rings", "rang", "will ring"], answer: 2, explain: "was about to 本身表示过去将来（正要…），when 引导的从句用一般过去时 rang。was/were about to + 动词原形 = 正要做某事（过去将来的一种表达）。" },
      { q: "—Uncle Sam said he ________ my birthday party, but he never showed up. —That's Uncle Sam. He forgets everything!", options: ["will attend", "would attend", "has attended", "had attended"], answer: 1, explain: "【解析】句意：Sam叔叔说他将参加我的生日聚会，但他从没出现。showed是过去时，said也是过去时，参加聚会是从过去角度看将来，用过去将来时would attend。规则：主句过去时→从句will变would。" },
      { q: "—What did Alice say? —She said she ______ me at eight o'clock tomorrow morning.", options: ["is calling", "was calling", "will call", "would call"], answer: 3, explain: "【解析】句意：爱丽丝说了什么？她说她明天上午八点给我打电话。站在过去角度看将来发生的动作，用过去将来时would call。" },
      { q: "—Would you like to go boating with me? —Sure. ______", options: ["I'd like", "I'd love", "I'll be glad", "I'd love to"], answer: 3, explain: "【解析】would like to do sth.是愿意去做某事，回答用I'd love/like to，to不能省略。" },
      { q: "—What did the teacher say to you just now? —She asked _______.", options: ["where did I buy the dictionary", "where I bought the dictionary", "where do I buy the dictionary", "where I buy dictionary"], answer: 1, explain: "【解析】考查宾语从句。一方面，宾语从句要用陈述语序；另一方面，主句是一般过去时，宾语从句也要用过去的某种时态，故选B。" },
      { q: "Who would you ___________ as your best friend?", options: ["choose", "to choose", "chose", "choosing"], answer: 0, explain: "【解析】句意：你会选择谁作为你最好的朋友。would是情态动词，后跟动词原形choose。" },
      { q: "Tim told us that his company ______ robots to do some of the work.", options: ["uses", "will use", "has used", "would use"], answer: 3, explain: "【解析】句意：Tim告诉我们他的公司将要使用机器人来做一些工作。主句told是过去时，从句也必须是过去的某种时态，用过去将来时would use。" },
      { q: "Too many people were absent. The chairperson warned that he ______ the meeting if necessary.", options: ["would cancel", "cancelled", "would start", "started"], answer: 0, explain: "【解析】句意：太多人缺席。主持人警告说如果有必要他将取消会议。warned是过去时，if表条件，主将从现结合用过去将来时would cancel。" },
      { q: "—What time shall we leave for the airport? —It's foggy today. I'm not sure ______ be closed soon. Let's go now.", options: ["whether the highway will", "whether will the highway", "when the highway will", "when will the highway"], answer: 0, explain: "【解析】考查宾语从句。宾语从句要用陈述句语序，B、D错；soon与when含义重复，C错。故选A。" },
      { q: "—Jack, what were you doing at nine last night? —I ______ homework at home.", options: ["do", "did", "was doing", "am doing"], answer: 2, explain: "【解析】句意：昨天晚上九点你在干什么？我在做作业。at nine last night是过去具体时刻，用过去进行时was doing。" },
      { q: "When I was a baby, Mom ______ for me after feeding me.", options: ["sang", "sing", "would sing", "sings"], answer: 2, explain: "【解析】句意：当我还是个宝宝时，妈妈会在喂我之后唱歌给我听。would+动词原形，表示过去习惯性的动作。" },
      { q: "He ______ every penny he earned on books.", options: ["would spend", "spend", "spent", "spends"], answer: 0, explain: "【解析】句意：他经常把赚的钱花在买书上。would+动词原形，表示过去习惯性的动作。" },
      { q: "Sina said she ______ to school the next Sunday.", options: ["wouldn't go", "isn't go", "didn't go", "won't go"], answer: 0, explain: "【解析】句意：希娜说她下周日不去学校了。站在过去角度看将来发生的动作，用过去将来时wouldn't go。" },
      { q: "She said that she ______ to the Zoo the next Sunday.", options: ["will go", "is going", "would go", "has gone"], answer: 2, explain: "【解析】句意：她说她下周日去动物园。the next Sunday表示过去将来，用过去将来时would go。" },
      { q: "She gave me a determined look—the kind that said she ______ her mind.", options: ["didn't change", "hadn't changed", "wouldn't change", "won't change"], answer: 2, explain: "【解析】句意：她给了我一个坚定的表情，表明她不会改变主意。宾语从句，主句gave/said是过去时，从句用过去将来时wouldn't change。" },
      { q: "I ______ go out to have a walk when they opened the door.", options: ["am about to", "was about to", "went to", "have to"], answer: 1, explain: "【解析】句意：他们开门时我正要出去散步。be about to do sth将要做某事，过去将来时为was/were about to。主语I用was。" },
      { q: "It was believed that the TV series The Legend of Miyue ______ millions of people soon.", options: ["would attract", "has attracted", "will attract", "attracted"], answer: 0, explain: "【解析】句意：人们相信《芈月传》很快会吸引数百万人。主句was believed是过去时，soon表示将来，用过去将来时would attract。" },
      { q: "Kate said that she ______ us as soon as she got home.", options: ["called", "calls", "will call", "would call"], answer: 3, explain: "【解析】句意：凯特说她一到家就给我们打电话。主句said是过去时，as soon as引导条件状语从句，主将从现原则，用过去将来时would call。" },
      { q: "Albert Einstein was born in 1879. As a child, few people guessed that he ______ a famous scientist whose theories would change the world.", options: ["has been", "had been", "was going to be", "was"], answer: 2, explain: "【解析】句意：爱因斯坦1879年出生，小时候很少人猜到他将会成为伟大的科学家。过去将来时was going to be表示从过去看将来要发生的事。后文would change也提示过去将来时。" },
      { q: "At college, Barack Obama didn't know that he ______ the first black president of the United States of America.", options: ["was to become", "becomes", "is to become", "became"], answer: 0, explain: "【解析】句意：在大学时，奥巴马不知道他将成为美国第一位黑人总统。过去将来时was to become表示过去某个时间将要发生的事情。" },
      { q: "Our TV set sells well, but ten years ago no one could have imagined such a big share in the market that they ______.", options: ["were to have", "had had", "were having", "had"], answer: 0, explain: "【解析】句意：我们的电视卖得好，但十年前没人能想象他们将会有这么大的市场份额。过去将来时were to have表示从过去看将来要发生的事。ten years ago是过去时间。" },
      { q: "The novel written by the author sells best, but five years ago no one could have imagined how great a role he ______ in the literary world.", options: ["was playing", "was to play", "had played", "played"], answer: 1, explain: "【解析】句意：这位作者的小说卖得最好，但五年前没人能想象他在文学世界中将扮演多伟大的角色。过去将来时was to play表示从过去看将来要发生的事。" },
      { q: "Tony has just arrived here, but I didn't know he ______ until yesterday.", options: ["would come", "had come", "came", "will come"], answer: 0, explain: "【解析】句意：托尼已到了，但我直到昨天才知道他要来。昨天才知道他要来，表示过去将来时would come。" },
      { q: "Just an hour ago he told me on the phone that he ______ home right after his work.", options: ["has come", "comes", "came", "would come"], answer: 3, explain: "【解析】句意：一小时前他在电话里说下班后马上回家。从过去看将来，用过去将来时would come。" },
      { q: "We were all surprised when he made it clear that he ________ office soon.", options: ["leaves", "would leave", "left", "had left"], answer: 1, explain: "【解析】句意：当他表示很快会离职时我们都很惊讶。made是过去时，soon表示将来，用过去将来时would leave。" },
      { q: "When I was a student, I ______ my homework every night.", options: ["do", "will do", "did", "would do"], answer: 3, explain: "【解析】句意：当我还是学生时，我每天晚上会做作业。would+动词原形，表示过去习惯性的动作。every night表示习惯。" },
      { q: "—What was your brother doing when you entered his room? —He ______ to the radio.", options: ["listens", "will listen", "listened", "was listening"], answer: 3, explain: "【解析】句意：当你走进房间时你哥哥在干什么？他在听收音机。问句是过去进行时，答语也用过去进行时was listening。" },
      { q: "John _______ so hard on his project that he didn't notice his mom enter the room.", options: ["works", "has worked", "was working", "will work"], answer: 2, explain: "【解析】句意：约翰学习如此努力以至于没注意到妈妈进房间。didn't notice是过去时，work当时正在进行，用过去进行时was working。" },
      { q: "—I called you at 8:00 last night, but you didn't answer. —Oh, I ________.", options: ["took a shower", "was taking a shower", "am taking a shower", "take a shower"], answer: 1, explain: "【解析】句意：昨晚八点给你打电话你没接。哦，我当时正在洗澡。at 8:00 last night用过去进行时was taking a shower。" },
      { q: "Sorry, I didn't see you, because I _________ a picture.", options: ["draw", "drew", "was drawing", "have drawn"], answer: 2, explain: "【解析】句意：对不起我没看见你，因为我在画一幅画。didn't see是过去时，当时正在画画用过去进行时was drawing。" },
      { q: "—What were you doing when the earthquake happened in Jianhe? —I ______ morning exercises.", options: ["do", "am doing", "was doing", "did"], answer: 2, explain: "【解析】句意：当剑河发生地震时你在做什么？我在做早操。问句是过去进行时，答语也用过去进行时was doing。" },
      { q: "Linda was busy when I went to see her yesterday. She ______ for an exam.", options: ["will study", "was studying", "has studied", "is studying"], answer: 1, explain: "【解析】句意：我昨天看到Linda时她很忙，正在为考试复习。went to see her yesterday是过去时间，当时正在复习用过去进行时was studying。" },
      { q: "—What were you doing at this time yesterday? —I ________ on the grass and drawing a picture.", options: ["sit", "sat", "am sitting", "was sitting"], answer: 3, explain: "【解析】句意：昨天这个时候你在做什么？我正坐在草地上画画。问句是过去进行时，答语也用过去进行时was sitting。" },
      { q: "Tom said he ______ basketball with his classmates from 4:00 to 6:00 yesterday afternoon.", options: ["is played", "was playing", "plays", "had played"], answer: 1, explain: "【解析】句意：汤姆说他昨天下午4点到6点正在和同学打篮球。from 4:00 to 6:00 yesterday afternoon是过去时间段，用过去进行时was playing。" },
      { q: "—Did you hear someone knock at the door just now? —Sorry, I ______ to my friend on the phone.", options: ["was talking", "talked", "am talking", "talk"], answer: 0, explain: "【解析】句意：你刚才听到有人敲门了吗？不好意思，我刚才在和朋友通电话。just now是过去时间，当时正在通话用过去进行时was talking。" },
      { q: "The engineers ______ a new computer in our classroom the whole yesterday morning, so we had our classes in the school hall.", options: ["were fixing", "fixed", "have fixed", "are fixing"], answer: 0, explain: "【解析】句意：昨天一上午工程师们都在我们教室安装新电脑，所以我们在学校大厅上课。the whole yesterday morning是过去持续时间段，用过去进行时were fixing。" }

    ]
  },
  t5: {
    icon: "🏃",
    intro: "现在进行时：表示现在正在进行的动作。结构：主语 + am/is/are + 动词-ing。常与 now, look, listen 等词连用。",
    questions: [
      { q: "Listen! The girl ______ in the next room.", options: ["sings", "sang", "is singing", "sing"], answer: 2, explain: "Listen! 提示动作正在发生，用现在进行时 is singing。现在进行时公式：am/is/are + 动词-ing。提示词：now, look, listen。" },
      { q: "We ______ for the bus now.", options: ["wait", "are waiting", "waited", "will wait"], answer: 1, explain: "now（现在）表示正在发生的动作，主语 We 用 are waiting。be 动词选择：I + am, He/She/It + is, You/We/They + are。" },
      { q: "Don't make noise. The baby ______.", options: ["sleeps", "slept", "is sleeping", "sleep"], answer: 2, explain: "Don't make noise 暗示宝宝正在睡觉，用现在进行时 is sleeping。语境推断：不让出声 → 正在睡。" },
      { q: "My mother ______ dinner in the kitchen.", options: ["cook", "cooks", "is cooking", "cooked"], answer: 2, explain: "正在厨房做饭是当前正在进行的动作，用 is cooking。没有明确时间词，但根据语境判断。没有时间词时，通过上下文判断是否正在进行。" },
      { q: "Look! Some boys ______ on the playground.", options: ["run", "runs", "is running", "are running"], answer: 3, explain: "Look! 提示正在发生，主语 Some boys 是复数，用 are running。run 的现在分词要双写 n 加 ing → running。重读闭音节结尾的动词，双写最后一个辅音字母再加 -ing。" },
      { q: "He ______ a book. He always reads at this time.", options: ["reads", "is reading", "read", "will read"], answer: 1, explain: "第一句描述当前正在做的事（is reading），第二句用一般现在时描述习惯。现在进行时 vs 一般现在时：正在做 vs 经常做。" },
      { q: "What ______ you ______?", options: ["are;doing", "do;do", "did;do", "are;do"], answer: 0, explain: "问对方正在做什么，用现在进行时疑问句：What are you doing? 疑问句结构：be动词提前 + 主语 + doing。be动词选择：I→am, you→are。" },
      { q: "I ______ an English song.", options: ["sing", "am singing", "sang", "sings"], answer: 1, explain: "表示此刻正在唱英文歌，用现在进行时 am singing。主语 I 配 am：I am singing。" },
      { q: "What ______ he ______?", options: ["is;mending", "does;mend", "did;mend", "is;mend"], answer: 0, explain: "问他正在修理什么，用现在进行时疑问句：What is he mending? 主语 he 配 is，mend+ing = mending。" },
      { q: "He ______ a car.", options: ["mends", "is mending", "mended", "mend"], answer: 1, explain: "表示他正在修车，用现在进行时 is mending。上下文与上一题呼应，正在进行的动作用 is + doing。" },
      { q: "______ you ______ a kite? Yes, I am.", options: ["Are;flying", "Do;fly", "Did;fly", "Are;fly"], answer: 0, explain: "一般疑问句用 Are you flying...? 肯定回答 Yes, I am. 疑问句结构：Are + 主语 + doing？fly 去 y 加 ied 是过去式，现在分词直接加 ing → flying。" },
      { q: "______ she ______ in the boat?", options: ["Is;sitting", "Does;sit", "Did;sit", "Is;siting"], answer: 0, explain: "一般疑问句用 Is she sitting...? sit 的现在分词要双写 t 加 ing → sitting。重读闭音节结尾双写最后一个辅音字母：sit→sitting, run→running, swim→swimming。" },
      { q: "______ you ______ questions?", options: ["Are;asking", "Do;ask", "Did;ask", "Are;ask"], answer: 0, explain: "问你们正在提问吗，用 Are you asking...? 主语 you 配 are，ask + ing = asking。疑问句结构：Are + 主语 + doing？" },
      { q: "We ______ games now.", options: ["play", "are playing", "played", "plays"], answer: 1, explain: "now 是现在进行时标志词，主语 We 配 are：are playing。now 提示动作正在发生。" },
      { q: "我在照看孩子。", options: ["I am looking after the baby.", "I'm look aftering the baby.", "I look am aftering the baby.", "I looking after the baby."], answer: 0, explain: "现在进行时结构：am/is/are + 动词-ing。look after 的现在分词是 looking after，不能拆开。正确：I am looking after the baby." },
      { q: "______ friend's making ______ a kite.", options: ["I;me", "My;my", "My;me", "His;his"], answer: 2, explain: "第一个空用形容词性物主代词 My 修饰 friend；第二个空用宾格 me 作 making 的宾语。My friend's making me a kite. = 我朋友正在给我做风筝。" },
      { q: "Is the woman ______ yellow your teacher?", options: ["in", "putting on", "wearing", "having"], answer: 0, explain: "in + 颜色表示「穿着…颜色衣服」，介词短语作后置定语。in yellow = 穿黄色衣服的。区别：put on 强调穿的动作，wear 强调穿着的状态，in + 颜色是固定搭配。" },
      { q: "Look! The twins ______ their mother do the housework.", options: ["are wanting", "help", "are helping", "are looking"], answer: 2, explain: "Look! 提示正在发生，the twins 是复数用 are helping。help sb. (to) do sth. 帮助某人做某事。want 通常不用进行时。" },
      { q: "______ are the birds doing? They are singing in a tree.", options: ["Who", "What", "How", "Where"], answer: 1, explain: "答句 They are singing 回答的是「在做什么」，用 What 提问。What are ... doing? 是现在进行时的经典句型。" },
      { q: "Is she ______ something?", options: ["eat", "eating", "eatting", "eats"], answer: 1, explain: "现在进行时疑问句 Is she + doing，eat + ing = eating。注意：eat 以不发音的 e... 实际上 eat 末尾的 t 不是不发音的，eat 直接加 ing → eating，不需要双写。" },
      { q: "你在干什么?", options: ["What is you doing?", "What are you do?", "What are you doing?", "What do you do?"], answer: 2, explain: "「你在干什么」用现在进行时：What are you doing? 主语 you 配 are。选项A错误(is→are)，选项B缺少-ing，选项D是一般现在时。" },
      { q: "What are you listening ______?", options: ["/", "for", "at", "to"], answer: 3, explain: "listen to 是固定搭配（听…）。listen 是不及物动词，后面必须加 to 才能接宾语。What are you listening to? = 你在听什么？" },
      { q: "我正在听他说话。", options: ["I listening to him.", "I'm listening to him.", "I'm listen to him.", "I'm listening him."], answer: 1, explain: "现在进行时：I am (I'm) + listening + to him。选项A缺be动词，选项C缺-ing，选项D缺to。listen to sb. 固定搭配。" },
      { q: "They are ______ their clothes.", options: ["makeing", "putting", "put away", "putting on"], answer: 3, explain: "putting on = 穿上（衣服），现在进行时 are putting on。make 的现在分词是 making（去e加ing）。put away = 收拾好。put 的现在分词双写 t → putting。" },
      { q: "Listen! She ______ in the classroom.", options: ["is singing", "sing", "to sing", "is sing"], answer: 0, explain: "Listen! 提示正在发生，用 is singing。现在进行时：is + 动词-ing。选项B缺be动词，选项C有to不定式，选项D没有-ing。" },
      { q: "Today Jim ______ his white shirt and brown trousers.", options: ["is putting on", "wear", "put on", "is wearing"], answer: 3, explain: "「穿着」表示状态用 wear 的进行时 is wearing。put on 强调「穿上」的瞬间动作。Today 表示今天的状态，用 is wearing 表示今天穿着。" },
      { q: "______ are you eating? I'm eating ______ meat.", options: ["What;some", "Which;any", "Where;not", "What;a"], answer: 0, explain: "问「在吃什么」用 What；回答用 some meat（一些肉）。meat 是不可数名词，用 some 修饰。肯定句用 some，否定/疑问句用 any。" },
      { q: "They ______ TV in the evening. They do their homework.", options: ["are watching", "can't watching", "don't watch", "don't watching"], answer: 2, explain: "in the evening + They do their homework 说明是日常习惯，用一般现在时否定 don't watch。不是正在进行的事。一般现在时否定：don't/doesn't + 原形。" },
      { q: "The children ______ football.", options: ["is playing", "are playing", "play the", "play a"], answer: 1, explain: "the children 是复数，用 are playing。球类运动前不加冠词：play football（不是 play the football）。现在进行时：are + playing。" },
      { q: "They are flying kites.", options: ["他们喜欢放风筝.", "他们在放风筝吗?", "他们在放风筝.", "他们常放风筝."], answer: 2, explain: "They are flying kites. 是现在进行时，表示「他们正在放风筝」。are flying = 正在放。选项A是喜欢，选项B是疑问句，选项D是一般现在时。" },
      { q: "Look, they are swimming in the river. I want ______ you.", options: ["to go with", "go with", "helping", "help"], answer: 0, explain: "want to do sth. 是固定搭配，用 to go with。want + to + 动词原形。不能用 want doing 或 want do。" },
      { q: "Look. Lucy is ______ a new bike today.", options: ["jumping", "running", "riding", "takeing"], answer: 2, explain: "ride a bike = 骑自行车，现在分词 ride→riding（去e加ing）。jump/run 与 bike 无关。take 的现在分词是 taking（去e加ing），不是 takeing。" },
      { q: "There ______ not ______ milk in the cup on the table.", options: ["are;many", "are;much", "is;many", "is;much"], answer: 3, explain: "milk 是不可数名词，be动词用 is；不可数名词用 much 修饰，不用 many。There be 句型：不可数名词用 is + much；可数名词复数用 are + many/数字。" },
      { q: "How many ______ are there in the room?", options: ["apple", "students", "milk", "paper"], answer: 1, explain: "How many 后接可数名词复数。apple 是单数（应为 apples），students 是复数；milk 和 paper 是不可数名词，用 How much 提问。" },
      { q: "Do you know if ______ a meeting next Sunday?", options: ["there was going to have", "there was going to be", "is there going to be", "there will be"], answer: 3, explain: "next Sunday 是将来时间，if 引导宾语从句用陈述语序（不倒装），用 there will be。选项B时态不一致（was→will），选项C语序错误（疑问语序）。There be 将来时：there will be / there is going to be。" },
      { q: "— Is this the last exam we have to take? — No, but there ______ another test three months later from now.", options: ["will be going to", "is", "will be", "has been"], answer: 2, explain: "three months later from now 是将来时间，用 there will be。There be 将来时最简形式：there will be + 名词。选项A结构错误，选项B时态不对，选项D是完成时。" },
      { q: "There ______ great changes in such kind of computers in the last few years.", options: ["is", "are", "will be", "have been"], answer: 3, explain: "in the last few years（在最近几年里）是现在完成时标志词，changes 是复数，用 there have been。There be 现在完成时：there have/has been + 名词。" },
      { q: "There ______ a film tomorrow evening.", options: ["will have", "have", "is going to be", "has"], answer: 2, explain: "tomorrow evening 是将来时间，用 there is going to be。注意：There be 句型不能用 have！There is going to be a film = 将有一场电影。" },
      { q: "There ______ a football match on TV this evening.", options: ["will have", "is going to be", "has", "is going to have"], answer: 1, explain: "this evening 表示将来，用 there is going to be。There be 句型不能用 have/has！常见错误：there will have ✗ → there will be ✓。" },
      { q: "There ______ a school at the foot of the hill.", options: ["have", "stand", "are", "stands"], answer: 3, explain: "There stands a school = 那里矗立着一所学校。stand/lie/sit 等动词可用于 There 句型表示存在，相当于 There is。a school 是单数，用 stands。" },
      { q: "There's going to ______ in tomorrow's newspapers.", options: ["have something new", "have new something", "be something new", "be new something"], answer: 2, explain: "be going to be + 某物。something 是不定代词，形容词 new 修饰不定代词时要后置：something new ✓，new something ✗。不能用 have。" },
      { q: "How many boys ______ there in Class one?", options: ["be", "is", "are", "am"], answer: 2, explain: "boys 是复数，用 are。How many + 复数名词 + are there...? 是 There be 句型的复数疑问句式。" },
      { q: "There ______ a lot of good news in today's newspaper.", options: ["is", "are", "was", "were"], answer: 0, explain: "news（消息）是不可数名词，视为单数，用 is。a lot of 既可以修饰可数名词也可以修饰不可数名词。注意：news 看起来像复数但实际是不可数名词！" },
      { q: "There ______ a pencil-box, two books and some flowers on the desk.", options: ["is a", "are some", "has a", "have some"], answer: 0, explain: "There be 就近原则：be 动词与最近的名词保持一致。a pencil-box 最近且是单数，用 is a。不能用 have/has，There be 句型表示存在。" },
      { q: "There ______ an apple and ten bananas in the basket. You can take any of them.", options: ["are", "is", "has", "have"], answer: 1, explain: "就近原则：an apple 最近且是单数，用 is。尽管后面有 ten bananas（复数），be 动词只与最近的名词一致。There is an apple and ten bananas." },
      { q: "______ any flowers on both sides of the street?", options: ["Is there", "Are there", "Has", "Have"], answer: 1, explain: "flowers 是复数，疑问句用 Are there...? There be 一般疑问句：Is/Are there + 名词？不能用 Has/Have。" },
      { q: "There ______ great changes in our country since 1982.", options: ["have been", "were", "has been", "are"], answer: 0, explain: "since 1982 是现在完成时标志词，changes 是复数，用 there have been。There be 现在完成时：there have/has been + 名词。since 搭配完成时。" },
      { q: "There is little water in the glass, ______?", options: ["isn't there", "isn't it", "is it", "is there"], answer: 3, explain: "little 表否定（几乎没有），反义疑问句前否后肯，用 is there? There be 反义疑问句用 there：There is...isn't there? / There is little...is there?" },
      { q: "— There is no air or water on the moon. Is there? — ____.", options: ["Yes, there are", "No, there isn't", "Yes, there isn't", "No, there is"], answer: 1, explain: "Is there? 是肯定疑问，但前面说 no air or water（没有），回答应一致用否定：No, there isn't. 注意：or 在否定句中连接两个名词表示「和」。" },
      { q: "— What did you see in the basket then? — There ______ a bottle of orange and some oranges.", options: ["is", "are", "was", "were"], answer: 2, explain: "then（那时）是过去时间，用过去时。就近原则：a bottle of orange 最近且是单数，用 was。orange 此处指橙汁（不可数），a bottle of orange = 一瓶橙汁。" },
      { q: "______ any flowers on both sides of the street?", options: ["Is there", "Are there", "Has", "Have"], answer: 1, explain: "flowers 是复数，疑问句用 Are there...? both sides 两侧，flowers 复数。There be 疑问句：be 动词提前 + there。" },
      { q: "______ is there on the table?", options: ["How many apples", "How much bread", "How much breads", "How many food"], answer: 1, explain: "How much + 不可数名词。bread 是不可数名词，没有复数形式（breads 错误）。food 也是不可数名词，应用 How much food。How many + 可数复数。" },
      { q: "There isn't ______ paper in the box. Will you go and get some for me?", options: ["any", "some", "a", "an"], answer: 0, explain: "否定句用 any。paper 是不可数名词，不能用 a/an。some 用于肯定句或请求句，any 用于否定和疑问句。There isn't any paper = 没有纸了。" },
      { q: "How many ______ are there in your classroom?", options: ["desks", "desk", "chair", "door"], answer: 0, explain: "How many 后接可数名词复数。desks 是复数；desk/chair/door 是单数。How many + 复数名词 + are there...?" },
      { q: "There ______ something wrong with our classroom.", options: ["are", "has", "is", "have"], answer: 2, explain: "something 是不定代词，视为单数，用 is。There is something wrong with... = ……出了毛病。不能用 have/has，这是 There be 句型。" },
      { q: "There is some ______ on the table.", options: ["apple", "orange", "cake", "sandwich"], answer: 1, explain: "some + 不可数名词。orange 此处指橙汁（不可数）。apple 和 sandwich 是可数名词（应为 some apples/sandwiches）。cake 可不可数两可，但 orange 更典型。" }
    ]
  },
  t6: {
    icon: "🏃‍♂️",
    intro: "过去进行时：表示过去某个时刻正在进行的动作。结构：主语 + was/were + 动词-ing。常与 at that time, at 8:00 yesterday 等连用。含中考真题与专项练习共66道，涵盖填空题转选择、课堂场景、故事情境等。",
    questions: [
      { q: "I ______ my homework at 8:00 last night.", options: ["do", "did", "was doing", "am doing"], answer: 2, explain: "at 8:00 last night（昨晚8点）是过去的具体时刻，用过去进行时 was doing。过去进行时公式：was/were + 动词-ing，表示过去某时刻正在做。" },
      { q: "While she ______ TV, her mother came in.", options: ["watches", "watched", "was watching", "is watching"], answer: 2, explain: "While 表示「当…的时候」，从句用过去进行时 was watching，主句 came in 是一般过去时。典型搭配：While + 过去进行时, 一般过去时。表示一个动作进行时另一个动作发生。" },
      { q: "They ______ basketball when it started to rain.", options: ["play", "played", "were playing", "are playing"], answer: 2, explain: "when it started to rain 是过去的时间点，主句「正在打篮球」用过去进行时 were playing。when + 一般过去时, 过去进行时：一个动作发生时，另一个正在做。" },
      { q: "What ______ you ______ at this time yesterday?", options: ["do;do", "did;do", "were;doing", "are;doing"], answer: 2, explain: "at this time yesterday（昨天这个时候）是过去的具体时刻，用过去进行时 were doing 提问。疑问句式：Was/Were + 主语 + 动词-ing？" },
      { q: "He fell asleep while he ______ the newspaper.", options: ["reads", "read", "was reading", "is reading"], answer: 2, explain: "fell asleep（睡着了）这个短暂动作发生时，正在看报纸（持续动作）用过去进行时 was reading。短暂动作用一般过去时，持续动作用过去进行时。" },
      { q: "I ______ along the street when I met an old friend.", options: ["walk", "walked", "was walking", "am walking"], answer: 2, explain: "when I met an old friend（当我遇到老朋友时），主句用过去进行时 was walking，表示「正走着」。中考经典句型：was/were doing when + 一般过去时。" },
      { q: "I called you at 8 o'clock last night, but there was no answer. What ______ you ______ at that time?", options: ["did; do", "were; doing", "are; doing", "do; do"], answer: 1, explain: "【答案解析】B。过去进行时的构成是was/were + 动词的现在分词形式。本题问的是昨晚8点那个时候你正在做什么，所以要用过去进行时。A选项是一般过去时，C选项是现在进行时，D选项是一般现在时，均不符合题意。" },
      { q: "My mother ______ dinner when I got home yesterday.", options: ["cooks", "cooked", "was cooking", "is cooking"], answer: 2, explain: "【答案解析】C。昨天我到家这个过去的时间点，妈妈正在做饭，要用过去进行时。A选项是一般现在时，B选项是一般过去时，D选项是现在进行时，都不正确。" },
      { q: "While I ______ my homework, my sister ______ TV.", options: ["did; watched", "was doing; watched", "did; was watching", "was doing; was watching"], answer: 3, explain: "【答案解析】D。while引导的时间状语从句，表示两个动作同时进行，都要用过去进行时。A和C选项时态搭配错误，B选项中后面的动作应该用过去进行时，所以正确答案是D。" },
      { q: "They ______ football on the playground from 4 to 5 yesterday afternoon.", options: ["play", "played", "are playing", "were playing"], answer: 3, explain: "【答案解析】D。昨天下午4点到5点是过去的一段时间，这段时间他们一直在操场上踢足球，要用过去进行时。A选项是一般现在时，B选项是一般过去时，C选项是现在进行时，均不符合。" },
      { q: "When the teacher came in, the students ______ about the movie.", options: ["talked", "were talking", "are talking", "talk"], answer: 1, explain: "【答案解析】B。老师进来这个过去的动作发生时，学生们正在谈论电影，用过去进行时。A选项是一般过去时，C选项是现在进行时，D选项是一般现在时，都不对。" },
      { q: "I ______ a shower when the phone rang.", options: ["take", "took", "was taking", "am taking"], answer: 2, explain: "【答案解析】C。电话响这个过去动作发生时，我正在洗澡，用过去进行时。A选项是一般现在时，B选项是一般过去时，D选项是现在进行时，不符合。" },
      { q: "She ______ to music at this time yesterday.", options: ["listens", "listened", "was listening", "is listening"], answer: 2, explain: "【答案解析】C。昨天这个时候她正在听音乐，用过去进行时。A选项是一般现在时，B选项是一般过去时，D选项是现在进行时，都不合适。" },
      { q: "What ______ you ______ at 9 o'clock last Sunday morning?", options: ["are; doing", "were; doing", "do; do", "did; do"], answer: 1, explain: "【答案解析】B。上周日上午9点是过去时间，问那时正在做什么用过去进行时。A选项是现在进行时，C选项是一般现在时，D选项是一般过去时，不正确。" },
      { q: "The kids ______ games in the garden when it started to rain.", options: ["play", "played", "are playing", "were playing"], answer: 3, explain: "【答案解析】D。开始下雨这个过去动作发生时，孩子们正在花园里玩游戏，用过去进行时。A选项是一般现在时，B选项是一般过去时，C选项是现在进行时，都不符合。" },
      { q: "I saw Tom in the library. He ______ a book at that moment.", options: ["reads", "read", "was reading", "is reading"], answer: 2, explain: "【答案解析】C。我看到汤姆时，他那个时候正在看书，用过去进行时。A选项是一般现在时，B选项是一般过去时，D选项是现在进行时，都不对。" },
      { q: "While the teacher ______ the blackboard, some students were whispering in the classroom.", options: ["was cleaning", "cleaned", "had cleaned", "has cleaned"], answer: 0, explain: "【答案解析】A。表示当老师正在擦黑板的时候，一些学生在教室里小声说话。过去进行时表示过去某个时刻正在进行的动作，was cleaning符合语境。B是一般过去时，C是过去完成时，D是现在完成时，均不符合。" },
      { q: "The students ______ an English song when the head teacher came in.", options: ["are singing", "were singing", "sang", "have sung"], answer: 1, explain: "【答案解析】B。班主任进来这个动作发生在过去，在那个时候学生们正在唱英文歌，用过去进行时were singing。A是现在进行时，C是一般过去时，D是现在完成时，不符合过去情境。" },
      { q: "I ______ my homework when my classmates were playing football outside.", options: ["am doing", "was doing", "did", "have done"], answer: 1, explain: "【答案解析】B。当同学们在外面踢足球的时候，我正在做我的作业，用过去进行时was doing。A是现在进行时，C是一般过去时，D是现在完成时，不符合语境。" },
      { q: "The English teacher ______ a grammar point when the bell rang.", options: ["was explaining", "explained", "had explained", "has explained"], answer: 0, explain: "【答案解析】A。铃声响这个动作发生在过去，在铃声响的时候英语老师正在讲解一个语法点，用过去进行时was explaining。B是一般过去时，C是过去完成时，D是现在完成时，均不符合。" },
      { q: "While the students ______ a group discussion, the teacher walked around the classroom.", options: ["are having", "were having", "had", "have had"], answer: 1, explain: "【答案解析】B。while引导的时间状语从句表示在某个时间段内正在进行的动作，学生们正在进行小组讨论，用过去进行时were having。A是现在进行时，C是一般过去时，D是现在完成时，不符合。" },
      { q: "Some students ______ their desks when the fire alarm went off.", options: ["were arranging", "arranged", "had arranged", "have arranged"], answer: 0, explain: "【答案解析】A。火警响起这个动作发生在过去，在火警响起的时候一些学生正在整理桌子，用过去进行时were arranging。B是一般过去时，C是过去完成时，D是现在完成时，均不符合。" },
      { q: "The headmaster ______ a speech while the students were listening attentively.", options: ["was making", "made", "had made", "has made"], answer: 0, explain: "【答案解析】A。学生们正在认真听这个动作发生在过去，在这个时间段校长正在做演讲，用过去进行时was making。B是一般过去时，C是过去完成时，D是现在完成时，均不符合。" },
      { q: "When I entered the classroom, the students ______ a drama performance.", options: ["are putting on", "were putting on", "put on", "have put on"], answer: 1, explain: "【答案解析】B。我进入教室这个动作发生在过去，在我进入教室的时候学生们正在进行戏剧表演，用过去进行时were putting on。A是现在进行时，C是一般过去时，D是现在完成时，不符合。" },
      { q: "The science teacher ______ an experiment when the power went out.", options: ["was conducting", "conducted", "had conducted", "has conducted"], answer: 0, explain: "【答案解析】A。停电这个动作发生在过去，在停电的时候科学老师正在进行一个实验，用过去进行时was conducting。B是一般过去时，C是过去完成时，D是现在完成时，均不符合。" },
      { q: "While the art students ______ their paintings, the art teacher walked among them.", options: ["are finishing", "were finishing", "finished", "have finished"], answer: 1, explain: "【答案解析】B。美术老师在学生中走动这个动作发生在过去，在这个时间段美术学生们正在完成画作，用过去进行时were finishing。A是现在进行时，C是一般过去时，D是现在完成时，不符合。" },
      { q: "A thief was trying to break into a house. While he ______ (try) to open the window, the police arrived.", options: ["was trying", "tried", "had tried", "tries"], answer: 0, explain: "【答案解析】A。当警察到达时小偷正在试图打开窗户，强调在过去某个时间点动作正在进行，用过去进行时was trying。B是一般过去时，C是过去完成时，D是一般现在时，均不符合语境。" },
      { q: "It was getting dark. While the parents ______ (set) up the tent, the kids were looking for firewood.", options: ["were setting", "set", "have set", "will set"], answer: 0, explain: "【答案解析】A。父母正在搭建帐篷，孩子们在找柴火，是过去某个时间段内两个动作同时进行，用过去进行时were setting。B是一般过去时，C是现在完成时，D是一般将来时，都不符合。" },
      { q: "While the director ______ (give) instructions to the other actors, Tom was practicing his lines alone in the corner.", options: ["was giving", "gave", "had given", "gives"], answer: 0, explain: "【答案解析】A。导演给其他演员指示和汤姆独自练习台词同时在过去发生，用过去进行时was giving。B是一般过去时，C是过去完成时，D是一般现在时，均不符合。" },
      { q: "In 1945, a soldier was writing a letter home. While he ______ (write), a bomb exploded nearby.", options: ["was writing", "wrote", "had written", "writes"], answer: 0, explain: "【答案解析】A。士兵正在写信和炸弹爆炸同时发生在过去，用过去进行时was writing。B是一般过去时，C是过去完成时，D是一般现在时，不符合情境。" },
      { q: "A little girl was flying a kite. While she ______ (fly) the kite, a dog came running towards her.", options: ["was flying", "flew", "had flown", "flies"], answer: 0, explain: "【答案解析】A。小女孩放风筝和狗跑向她同时在过去发生，用过去进行时was flying。B是一般过去时，C是过去完成时，D是一般现在时，都不符合。" },
      { q: "While the teacher ______ (explain) the history of the vase, Lily was taking careful notes.", options: ["was explaining", "explained", "had explained", "explains"], answer: 0, explain: "【答案解析】A。老师讲解花瓶历史和莉莉做笔记同时在过去进行，用过去进行时was explaining。B是一般过去时，C是过去完成时，D是一般现在时，均不符合。" },
      { q: "A man was driving his car on the country road. While he ______ (drive), he saw a figure standing by the roadside.", options: ["was driving", "drove", "had driven", "drives"], answer: 0, explain: "【答案解析】A。男人开车和看到路边身影同时在过去发生，用过去进行时was driving。B是一般过去时，C是过去完成时，D是一般现在时，不符合情景。" },
      { q: "A couple was dancing in the middle of the room. While they ______ (dance), the lights suddenly went out.", options: ["were dancing", "danced", "had danced", "dances"], answer: 0, explain: "【答案解析】A。这对夫妇跳舞和灯突然熄灭同时在过去发生，用过去进行时were dancing。B是一般过去时，C是过去完成时，D是一般现在时，不符合场景。" },
      { q: "A young explorer was walking through the forest. While he ______ (walk), he found a strange plant under a big tree.", options: ["was walking", "walked", "had walked", "walks"], answer: 0, explain: "【答案解析】A。探险家走路和发现奇怪植物同时在过去发生，用过去进行时was walking。B是一般过去时，C是过去完成时，D是一般现在时，不符合情境。" },
      { q: "A group of firefighters was called to a burning building. While they ______ (enter) the building, they heard a cry for help from the second floor.", options: ["were entering", "entered", "had entered", "enters"], answer: 0, explain: "【答案解析】A。消防员进入大楼和听到求救声同时在过去发生，用过去进行时were entering。B是一般过去时，C是过去完成时，D是一般现在时，不符合救援场景。" },
      { q: "I ______ (have) my breakfast at half past six yesterday morning.", options: ["have", "had", "was having", "am having"], answer: 2, explain: "【答案解析】at half past six yesterday morning是过去的具体时刻，表示当时正在吃早餐，用过去进行时was having。" },
      { q: "Mary ______ (go) over her lessons from six to seven last night. John and Peter ______ (do) the same thing.", options: ["went; did", "was going; were doing", "go; do", "is going; are doing"], answer: 1, explain: "【答案解析】from six to seven last night是过去的一段时间，表示在这段时间内正在进行的动作，用过去进行时。Mary是单数用was going，John and Peter是复数用were doing。" },
      { q: "What ______ you ______ (do) at that time? We ______ (watch) TV.", options: ["did; do; watched", "were; doing; were watching", "do; do; watch", "are; doing; are watching"], answer: 1, explain: "【答案解析】at that time是过去的具体时刻，用过去进行时were doing提问，回答也用过去进行时were watching。" },
      { q: "Was your father at home yesterday evening? Yes, he was. He ______ (listen) to the radio.", options: ["listens", "listened", "was listening", "is listening"], answer: 2, explain: "【答案解析】Yes, he was表明用过去时，且正在听收音机是当时正在进行的动作，用过去进行时was listening。" },
      { q: "They ______ (not make) a model ship when I saw him.", options: ["didn't make", "weren't making", "don't make", "aren't making"], answer: 1, explain: "【答案解析】when I saw him是过去的时间点，当时他们正在做模型船（否定），用过去进行时否定weren't making。" },
      { q: "______ they ______ (have) a meeting at 4 yesterday afternoon? No, they ______. They ______ (clean) the classroom.", options: ["Did; have; didn't; cleaned", "Were; having; weren't; were cleaning", "Do; have; don't; clean", "Are; having; aren't; are cleaning"], answer: 1, explain: "【答案解析】at 4 yesterday afternoon是过去的具体时刻，疑问句用Were...having? 否定回答weren't，他们正在打扫教室用were cleaning。" },
      { q: "______ it ______ (rain) when you left school? Yes, it ______.", options: ["Did; rain; did", "Was; raining; was", "Does; rain; does", "Is; raining; is"], answer: 1, explain: "【答案解析】when you left school是过去的时间点，当时正在下雨，用过去进行时Was...raining? 肯定回答was。" },
      { q: "What ______ your father ______ (do) when he was your age?", options: ["did; do", "was; doing", "does; do", "is; doing"], answer: 1, explain: "【答案解析】when he was your age是过去的时间段，问当时正在做什么，用过去进行时was...doing?" },
      { q: "One day, Edison ______ (wait) for a train to arrive, and suddenly a little boy ran to the track.", options: ["waited", "was waiting", "waits", "is waiting"], answer: 1, explain: "【答案解析】and suddenly a little boy ran是突发的过去动作，Edison当时正在等火车是背景动作，用过去进行时was waiting。" },
      { q: "He asked me if I ______ (go) fishing that afternoon.", options: ["went", "would go", "was going", "go"], answer: 1, explain: "【答案解析】主句asked是过去时，宾语从句用过去将来时would go（主过从过原则）。that afternoon表示从过去看将来。was going也可表示过去打算。" },
      { q: "The three of them were in a hurry because their plane ______ (leave) in five minutes.", options: ["left", "was leaving", "would leave", "leaves"], answer: 1, explain: "【答案解析】in five minutes表示即将发生，were in a hurry是过去时，飞机即将起飞用过去进行时was leaving表即将发生的动作。" },
      { q: "In a letter, John told us that he ______ (come) to China next month.", options: ["came", "would come", "was coming", "comes"], answer: 1, explain: "【答案解析】told是过去时，next month表示将来，宾语从句用过去将来时would come（主过从过原则）。was coming也可表过去将来计划。" },
      { q: "When the bell rang, Jenny ______ (wait) in her seat.", options: ["waited", "was waiting", "waits", "is waiting"], answer: 1, explain: "【答案解析】when the bell rang是过去的时间点，Jenny当时正在座位上等着，用过去进行时was waiting。" },
      { q: "She ______ (make) her dress the whole afternoon.", options: ["made", "was making", "makes", "is making"], answer: 1, explain: "【答案解析】the whole afternoon是过去的一段持续时间段，表示整个下午都在做裙子，用过去进行时was making。" },
      { q: "While my father ______ (look) through the evening paper, he suddenly ______ a cry.", options: ["was looking; heard", "looked; was hearing", "was looking; was hearing", "looked; heard"], answer: 0, explain: "【答案解析】while引导的时间状语从句用过去进行时was looking（背景动作），suddenly表示突发动作用一般过去时heard（hear a cry=听到一声喊叫）。" },
      { q: "I ______ a meal when you ______ me.", options: ["cooked; were ringing", "was cooking; rang", "was cooking; were ringing", "cooked; rang"], answer: 1, explain: "【答案解析】when you rang me是过去的突发动作，我当时正在做饭是背景动作，用过去进行时was cooking + 一般过去时rang。" },
      { q: "He said he ______ to draw a plane on the blackboard at that time.", options: ["tries", "tried", "was trying", "will try"], answer: 2, explain: "【答案解析】at that time是过去的具体时刻，he said是过去时，后面用过去进行时was trying表示当时正在试着画画。" },
      { q: "While she ______ TV, she ______ a sound outside the room.", options: ["was watching; was hearing", "watched; was hearing", "watched; heard", "was watching; heard"], answer: 3, explain: "【答案解析】while引导从句用过去进行时was watching（背景），听到声音是突发动作用一般过去时heard。hear是感官动词不用进行时。" },
      { q: "They ______ a football game from 7 to 9 last night.", options: ["were watching", "watch", "watched", "are watching"], answer: 0, explain: "【答案解析】from 7 to 9 last night是过去的一段时间，表示这段时间一直在看比赛，用过去进行时were watching。" },
      { q: "What book ______ you ______ when I ______ you at four yesterday afternoon?", options: ["did; read; was seeing", "did; read; saw", "were; reading; saw", "were; reading; was seeing"], answer: 2, explain: "【答案解析】at four yesterday afternoon是过去的具体时刻，问当时正在读什么书用过去进行时were reading。when I saw you中saw是一般过去时（see不用进行时）。" },
      { q: "It was Friday evening. Mr and Mrs. Green ______ ready to fly to England.", options: ["are getting", "get", "were getting", "got"], answer: 2, explain: "【答案解析】It was Friday evening是过去时间，Mr and Mrs. Green是复数，正在做准备用过去进行时were getting。" },
      { q: "Lei Feng ______ always ______ of others when he ______ in the army.", options: ["is; thinking; was", "was; thinking; is", "did; think; is", "was; thinking; was"], answer: 3, explain: "【答案解析】when he was in the army是过去时间段，always与过去进行时搭配表示过去一贯的动作。was always thinking of others=总是为别人着想。三空都用过去时。" },
      { q: "A girl ______ my pen fall off the table when she ______ me.", options: ["saw; passed", "was seeing; passed", "saw; was passing", "was seeing; was passing"], answer: 0, explain: "【答案解析】see是感官动词不用进行时，用一般过去时saw。when she passed me是过去的突发动作，用一般过去时passed。see sb. do sth.=看到某人做某事。" },
      { q: "We ______ for Tom at ten last Sunday. He often kept us ______.", options: ["were waiting; waiting", "were waiting; wait", "waited; waiting", "waited; wait"], answer: 0, explain: "【答案解析】at ten last Sunday是过去的具体时刻，用过去进行时were waiting。keep sb. doing是固定搭配，kept us waiting=让我们一直等。" },
      { q: "He ______ his father on the farm the whole afternoon last Saturday.", options: ["helps", "would help", "was helping", "is helping"], answer: 2, explain: "【答案解析】the whole afternoon last Saturday是过去的一段持续时间段，用过去进行时was helping表示整个下午都在帮忙。" },
      { q: "While mother ______ some washing, I ______ a kite for Kate.", options: ["did; made", "was doing; made", "was doing; was making", "did; was making"], answer: 1, explain: "【答案解析】while引导从句用过去进行时was doing（背景动作），I made a kite是完成的动作用一般过去时made。典型搭配：While + 过去进行时, 一般过去时。" },
      { q: "\"______ you angry then?\" \"They ______ too much noise.\"", options: ["are; were making", "were; were making", "are; made", "were; made"], answer: 1, explain: "【答案解析】then表示过去时间，用Were you angry? 他们正在制造噪音用过去进行时were making too much noise。" },
      { q: "He ______ some cooking at that time, so ______ me.", options: ["did; heard", "did; didn't hear", "was doing; heard", "was doing; didn't hear"], answer: 3, explain: "【答案解析】at that time是过去的具体时刻，用过去进行时was doing。so表示结果，因此没听到我用didn't hear（一般过去时否定）。" },
      { q: "This time yesterday Jack ______ his bike. He ______ TV.", options: ["repaired; didn't watch", "was repairing; watched", "repaired; watched", "was repairing; wasn't watching"], answer: 3, explain: "【答案解析】this time yesterday是过去的时刻，两个动作同时在进行：was repairing his bike和wasn't watching TV，都用过去进行时。" },
      { q: "His parents wanted to know how he ______ on with his new classmates.", options: ["was getting", "gets", "is getting", "will get"], answer: 0, explain: "【答案解析】wanted是过去时，宾语从句用过去时态，how he was getting on with=他与新同学相处得如何，用过去进行时was getting表示当时的情况。" }

    ]
  },
  t7: {
    icon: "✅",
    intro: "现在完成时：表示过去发生的动作对现在有影响，或从过去持续到现在的动作。结构：主语 + have/has + 过去分词。常与 already, yet, ever, never, since, for 等连用。含中考语法综合练习36道，涵盖冠词、比较级、动名词、名词复数、条件状语从句、定语从句、宾语从句、主谓一致、情态动词、现在完成时标志词、短暂性动词与持续性动词、have been to/gone to/in辨析、反意疑问句等考点。",
    questions: [
      { q: "I ______ my homework already.", options: ["finish", "finished", "have finished", "finishing"], answer: 2, explain: "already（已经）是现在完成时的标志词，用 have finished。现在完成时公式：have/has + 过去分词。标志词：already, yet, just, ever, never。" },
      { q: "She ______ in this city since 2015.", options: ["lives", "lived", "has lived", "is living"], answer: 2, explain: "since 2015（自从2015年）表示从过去持续到现在的状态，用现在完成时 has lived。since + 时间点 / for + 时间段 → 现在完成时。" },
      { q: "Have you ______ been to the Great Wall?", options: ["ever", "yet", "already", "just"], answer: 0, explain: "ever 表示「曾经」，常用于现在完成时的疑问句中。Have you ever been to...? 意为「你曾经去过…吗？」ever 用于疑问句，never 用于否定句。" },
      { q: "He hasn't finished his work ______.", options: ["already", "yet", "ever", "just"], answer: 1, explain: "yet 用于现在完成时的否定句和疑问句，放在句末，表示「还（没）」。already 用于肯定句，yet 用于否定句和疑问句。" },
      { q: "I ______ my key. I can't find it now.", options: ["lose", "lost", "have lost", "am losing"], answer: 2, explain: "I can't find it now 说明过去丢钥匙的动作对现在有影响（现在找不到了），用现在完成时 have lost。现在完成时强调过去动作对现在的影响。" },
      { q: "They ______ each other for ten years.", options: ["know", "knew", "have known", "are knowing"], answer: 2, explain: "for ten years（十年了）是时间段，表示从过去认识持续到现在，用现在完成时 have known。for + 时间段 → 现在完成时。注意：know 无进行时。" },
      { q: "—Do you know _________ girl sitting behind Tony? —Oh, she is Tony's sister. She is _________ nurse.", options: ["a; a", "the; the", "the; a", "a; the"], answer: 2, explain: "【答案解析】第一空：特指坐在Tony后面的那个女孩，用定冠词the（特指）；第二空：表示职业，一名护士，用不定冠词a（泛指一个）。故选C。" },
      { q: "The more books you read, the _________ you will feel.", options: ["more exciting", "more excited", "exciting", "excited"], answer: 1, explain: "【答案解析】The more...the more...（越...越...）句型，两处都用比较级。excited修饰人（感到兴奋的），exciting修饰事物（令人兴奋的）。人感到兴奋用more excited。故选B。" },
      { q: "I'm good at _________, but Jim is not.", options: ["play football", "to play football", "playing football", "playing the football"], answer: 2, explain: "【答案解析】be good at + doing sth.是固定搭配，后接动名词，用playing。球类运动前不加冠词：play football（不是play the football）。故选C。" },
      { q: "She said that three _________ and four _________ would come here.", options: ["German; French", "Germans; Frenchmans", "Germans; Frenchmen", "Germen; Frenchmen"], answer: 2, explain: "【答案解析】German的复数是Germans（直接加s）；Frenchman的复数是Frenchmen（man变men）。故选C。注意：Germen是错误形式，Frenchmans也是错误的。" },
      { q: "We don't know if it _________ later. If it _________, we won't go to see Mr. Wang.", options: ["rains; will rain", "rains; rain", "will rain; will rain", "will rain; rains"], answer: 3, explain: "【答案解析】第一空：if引导宾语从句（是否），表示将来的事用将来时will rain；第二空：if引导条件状语从句，主将从现（主句won't go用将来时，从句用一般现在时rains）。两个if用法不同。故选D。" },
      { q: "We should be ready to help the people _________ are in trouble.", options: ["whose", "whom", "which", "who"], answer: 3, explain: "【答案解析】定语从句，先行词the people是人，关系代词在从句中作主语（are in trouble），用who引导。whose表所属关系，whom作宾语，which修饰物。故选D。" },
      { q: "—Excuse me. Would you tell me ____________? —Sorry, I'm a stranger here.", options: ["how can I get to the hospital", "how I can get to the hospital", "when can I get to the hospital", "when I can to the hospital"], answer: 1, explain: "【答案解析】宾语从句用陈述语序（主语+谓语），排除A和C（疑问语序）。D选项can to get语法错误（can后接动词原形，不接to）。故选B：how I can get to the hospital。" },
      { q: "—Peter's brother eats too much sweet food. —____________!", options: ["So does he", "So he does", "So is he", "So he is"], answer: 1, explain: "【答案解析】So + 主语 + 助动词表示赞同对方的话，意为「确实如此」。Peter's brother eats too much sweet food. 回答So he does = 他确实如此。注意与So + 助动词 + 主语（也如此）区分。故选B。" },
      { q: "Everyone except Tom and John ____________ there when the class began.", options: ["is", "are", "was", "were"], answer: 2, explain: "【答案解析】Everyone作主语视为单数，except Tom and John不影响主语的单复数。when the class began是过去时，用was（单数过去时）。故选C。" },
      { q: "—Listen! Helen is singing in the next room. —It ____________ be Helen. She has gone to Beijing.", options: ["can't", "mustn't", "may", "should"], answer: 0, explain: "【答案解析】She has gone to Beijing（她已经去北京了）说明Helen不在这里，所以不可能是她在唱歌，用can't表示否定推测（不可能）。mustn't表示禁止，may表示可能推测，should表示应该。故选A。" },
      { q: "Both his parents look sad. Maybe they _________ what's happened to him.", options: ["knew", "have known", "must know", "will know"], answer: 2, explain: "【答案解析】句意：他的父母看起来很伤心。也许他们一定知道他出了什么事。must表示推测（一定），用must know。knew是过去时，与what's happened（现在完成时）不搭配；have known表示已经知道，但know是状态动词，have known暗示早已知道，不合语境；will know是将来时，不符合。故选C。" },
      { q: "He has _______ been to Shanghai, has he?", options: ["already", "never", "ever", "still"], answer: 1, explain: "【答案解析】反意疑问句has he?是肯定形式，说明前半句是否定句，用never（否定词）。前否后肯：has never → has he? already用于肯定句，ever用于疑问句，still不合题意。故选B。" },
      { q: "Have you met Mr Li ______?", options: ["just", "ago", "before", "a moment ago"], answer: 2, explain: "【答案解析】before可用于现在完成时句末，表示以前见过。just通常放在have/has之后（have just met）；ago和a moment ago用于一般过去时。故选C。" },
      { q: "The famous writer ______ one new book in the past two years.", options: ["is writing", "was writing", "wrote", "has written"], answer: 3, explain: "【答案解析】in the past two years（过去两年里）是现在完成时标志词，用has written。现在完成时公式：have/has + 过去分词。故选D。" },
      { q: "—Our country ______ a lot so far. —Yes. I hope it will be even ______.", options: ["has changed; well", "changed; good", "has changed; better", "changed; better"], answer: 2, explain: "【答案解析】so far（到目前为止）是现在完成时标志词，用has changed。even后接比较级，good的比较级是better（even better = 更好）。故选C。" },
      { q: "Zhao Lan ______ already ______ in this school for two years.", options: ["was; studying", "will; study", "has; studied", "are; studying"], answer: 2, explain: "【答案解析】already和for two years都是现在完成时标志词，用has studied。现在完成时公式：have/has + 过去分词。故选C。" },
      { q: "We ______ Xiao Li since she was a little girl.", options: ["know", "had known", "have known", "knew"], answer: 2, explain: "【答案解析】since she was a little girl表示从过去持续到现在，用现在完成时have known。know是状态动词，用现在完成时表示持续状态。故选C。" },
      { q: "Harry Potter is a very nice film. I ______ it twice.", options: ["will see", "have seen", "saw", "see"], answer: 1, explain: "【答案解析】twice表示看过两次，对现在有影响（已经知道内容），用现在完成时have seen。故选B。" },
      { q: "—These farmers have been to the United States. —Really? When ______ there?", options: ["will they go", "did they go", "do they go", "have they gone"], answer: 1, explain: "【答案解析】have been to表示去过已回来。问什么时候去的用一般过去时did they go（问过去的动作）。故选B。" },
      { q: "—______ you ______ your homework yet? —Yes. I ______ it a moment ago.", options: ["Did; do; finished", "Have; done; finished", "Have; done; have finished", "will; do; finish"], answer: 1, explain: "【答案解析】yet是现在完成时标志词，第一空用Have; done。a moment ago是过去时间，第二空用一般过去时finished。故选B。" },
      { q: "His father ______ the Party since 1978.", options: ["joined", "has joined", "was in", "has been in"], answer: 3, explain: "【答案解析】since 1978要求持续状态。join是短暂性动词，不能与since连用（has joined错误）。用has been in表示入党并持续到现在。故选D。" },
      { q: "—Do you know him well? —Sure. We _________ friends since ten years ago.", options: ["were", "have been", "have become", "have made"], answer: 1, explain: "【答案解析】since ten years ago表示从过去持续到现在，用现在完成时have been。become是短暂性动词，不能与since连用。故选B。" },
      { q: "—How long have you ______ here? —About two months.", options: ["been", "gone", "come", "arrived"], answer: 0, explain: "【答案解析】How long问多长时间，需要持续性动词。用have been here表示在这里待了。gone/come/arrived都是短暂性动词，不能与How long连用。故选A。" },
      { q: "Hurry up! The play __________ for ten minutes.", options: ["has begun", "had begun", "has been on", "began"], answer: 2, explain: "【答案解析】for ten minutes要求持续状态。begin是短暂性动词，不能与for连用。用has been on表示演出已经开始了十分钟（持续状态）。故选C。" },
      { q: "It ______ ten years since he left the army.", options: ["is", "has", "will", "was"], answer: 0, explain: "【答案解析】It is + 时间段 + since...是固定句型，用一般现在时is。表示自从他离开军队已经十年了。故选A。" },
      { q: "Miss Green isn't in the office. She _______ to the library.", options: ["has gone", "went", "will go", "has been"], answer: 0, explain: "【答案解析】isn't in the office说明她去了还没回来，用has gone to（去了未回）。has been to表示去过已回来，不合语境。故选A。" },
      { q: "My parents ______ Shandong for ten years.", options: ["have been in", "have been to", "have gone to", "have been"], answer: 0, explain: "【答案解析】for ten years要求持续状态，用have been in表示在山东待了十年。have been to表示去过已回来，have gone to表示去了未回，都不合题意。故选A。" },
      { q: "The students have cleaned the classroom, ______?", options: ["so they", "don't they", "have they", "haven't they"], answer: 3, explain: "【答案解析】前肯定后否定：have cleaned（肯定）→ haven't they?（否定反意疑问）。故选D。" },
      { q: "______ has Mr White been a member of Greener China since he ______ to China?", options: ["How soon; comes", "How often; got", "How long; came", "How far; arrived"], answer: 2, explain: "【答案解析】How long问多长时间（与since搭配），since从句用一般过去时came to China。How soon问多久以后，How often问频率，How far问距离。故选C。" },
      { q: "His uncle ______ for more than 9 years.", options: ["has come here", "has started to work", "has lived there", "has left the university"], answer: 2, explain: "【答案解析】for more than 9 years要求持续状态。come/start/leave都是短暂性动词，不能与for连用。live是持续性动词，用has lived there。故选C。" }

    ]
  },
  t8: {
    icon: "⏪",
    intro: "过去完成时：表示在过去某一时间之前已经完成的动作，即「过去的过去」。结构：主语 + had + 过去分词。常与 by the time, before, after 等连用。含中考过去完成时专项练习56道，涵盖by the time句型、before/after从句、宾语从句中的过去完成时、短暂性动词与延续性动词转换、过去完成时标志词等考点。",
    questions: [
      { q: "When I got to the station, the train ______.", options: ["left", "had left", "has left", "leaves"], answer: 1, explain: "火车离开（had left）发生在我到达车站（got）之前，即「过去的过去」，用过去完成时。过去完成时 = had + 过去分词，表示比一般过去时更早的动作。" },
      { q: "She ______ English for 5 years before she moved to London.", options: ["learns", "learned", "had learned", "has learned"], answer: 2, explain: "学英语（had learned）发生在她搬到伦敦（moved）之前，用过去完成时。before + 一般过去时, 主句用过去完成时。" },
      { q: "By the time he arrived, we ______ all the food.", options: ["eat", "ate", "had eaten", "have eaten"], answer: 2, explain: "By the time he arrived（到他到达时），吃光食物是之前完成的动作，用 had eaten。By the time + 一般过去时, 主句用过去完成时。" },
      { q: "He said he ______ the film before.", options: ["sees", "saw", "had seen", "has seen"], answer: 2, explain: "He said 是过去时，从句中「看过电影」发生在 said 之前，用过去完成时 had seen。宾语从句中：主句过去时，从句如表示更早的动作用过去完成时。" },
      { q: "I realized I ______ my book at home.", options: ["leave", "left", "had left", "have left"], answer: 2, explain: "把书忘在家（had left）发生在我意识到（realized）之前，用过去完成时。realized/knew/found 等动词后的宾语从句常需要过去完成时。" },
      { q: "After he ______ his homework, he went to bed.", options: ["finishes", "finished", "had finished", "has finished"], answer: 2, explain: "After 从句中「完成作业」发生在上床睡觉（went）之前，用过去完成时 had finished。After + 过去完成时, 主句用一般过去时。" },
{ q: "Dad ______ TV when it began to rain yesterday.", options: ["watches", "watched", "is watching", "was watching"], answer: 3, explain: "【答案解析】句意：昨天开始下雨时，爸爸正在看电视。watch TV，看电视，固定结构。A一般现在时；B一般过去时；C现在进行时；D过去进行时。结合题干中的when it began to rain yesterday，可知此空要用过去进行时，故答案为D。" },
      { q: "She said her family ______ ______ the army during the war.", options: ["has hidden; from", "had hidden; from", "has hidden; with", "had hidden; with"], answer: 1, explain: "【答案解析】句意：她说她的家人在战争期间隐藏他们自己躲开了军队。由主句谓语动词said可知，从句应用过去的某一种时态，所以排除A、C两项；又因hide sb. from sb.为固定搭配，躲着某人，所以排除D项。故选B。" },
      { q: "Most of my good friends ______ when I ______ at the party.", options: ["left; had arrived", "had left; arrived", "left; arrived", "had left; had arrived"], answer: 1, explain: "【答案解析】句意：当我到达聚会时，我的大部分好朋友已经离开了。根据句意可知\"到达聚会\"用一般过去时，\"离开\"的动作发生在\"到达聚会\"之前，应用过去完成时，故选B。" },
      { q: "—Why was he late for school yesterday? —He got up late. By the time he got to the bus stop, the bus ______ already ______.", options: ["was; leaving", "has; left", "would; leave", "had; left"], answer: 3, explain: "【答案解析】句意：——昨天他为什么迟到了？——他起床晚了。他到达公共汽车站时，公共汽车已经离开了。结合语境可知此处应用过去完成时，故选D。" },
      { q: "—Did you see Mrs. Lee in the meeting room? —No. When I got there, she ______ another meeting.", options: ["had left for", "had left to", "was leaving for", "was leaving to"], answer: 0, explain: "【答案解析】句意：——你看见李太太在会议室了吗？——没有。当我到那里时，她已经动身去下一场会议了。A项和B项为过去完成时，C项和D项为过去进行时。根据When I got there从句中为一般过去时，可知当我过去到达那里的时候，她已经离开了，因此主句中应用过去完成时。排除C和D。leave for离开某地去另一地，leave to把某物留给...。故选A。" },
      { q: "By the time we ______ to the cinema, the movie ______.", options: ["got; had begun", "have got; had begun", "got; began", "had got; begun"], answer: 0, explain: "【答案解析】句意：当我们到达电影院时电影已经开始了。这是一个复合句，by the time后加过去时间发生的动作，主句谓语动词常用过去完成时态，故选A。" },
      { q: "The young man sitting next to me on the plane was very nervous. He ______ before.", options: ["doesn't fly", "didn't fly", "hasn't flown", "hadn't flown"], answer: 3, explain: "【答案解析】句意：在飞机上坐在我旁边的那个年轻人非常紧张，他以前没有坐过飞机。根据was可知，紧张的动作发生在过去，再根据before可知，没坐过飞机的动作发生在\"过去的过去\"，用过去完成时。故选D。" },
      { q: "—Did you see the manager this morning? —No. He ______ for Beijing by the time I arrived at his office.", options: ["has left", "left", "was leaving", "had left"], answer: 3, explain: "【答案解析】句意：——你今天早上见到经理了吗？——没有。我到他的办公室时，他已经去北京了。A现在完成时；B过去式；C过去进行时；D过去完成时。by the time到...时候为止。由arrived过去式可知，表示过去的过去，用过去完成时，结构是had+动词的过去分词。故选D。" },
      { q: "When I got to the concert, I realized that I ______ my ticket at home.", options: ["have left", "left", "had left", "leave"], answer: 2, explain: "【答案解析】句意：当我到了演唱会时，我意识到我把票落在家里了。根据I realized，可知此句用过去完成时，其构成为had＋done，故选C。" },
      { q: "By the time I got back to school, the bell ______.", options: ["rang", "has rung", "had rung", "ring"], answer: 2, explain: "【答案解析】句意：当我回到学校时，铃已经响了。根据By the time I got back to school，可知主句用过去完成时，其构成为had＋done，故选C。" },
      { q: "—Were you in time for the film yesterday? —No, we were late. It ______ when I ______ to the cinema.", options: ["has begun; get", "had begun; got", "would begin; got", "has been on; get"], answer: 1, explain: "【答案解析】句意：——你昨天赶上看电影了吗？——不，我们迟到了。当我到电影院时，电影已经开始了。根据Were you in time for the film yesterday?及答语No，可知\"到达\"的动作发生在过去，时态为一般过去时got；\"电影开始\"的动作发生在过去的过去，时态为过去完成时had begun。故选B。" },
      { q: "Mrs. Jackson ______ many interesting comic strips created by her students by the end of 2018.", options: ["received", "has received", "will receive", "had received"], answer: 3, explain: "【答案解析】句意：到2018年底，杰克逊夫人收到了许多由她的学生创作的有趣的漫画。根据by the end of 2018可知，此处描述的是过去的过去，用过去完成时，用had done形式，故选D。" },
      { q: "By the end of last month, Jessica ______ reading Harry Potter and the Sorcerer's Stone.", options: ["finished", "has finished", "had finished", "would finish"], answer: 2, explain: "【答案解析】句意：到上个月末，Jessica已经读完了《哈利波特与魔法石》。由句中的时间状语By the end of last month可知，这里表示到上个月底已经...，by+过去的时间，应用过去完成时态。故答案选C。" },
      { q: "My sister ______ in Shanghai University for 4 years before she went to Beijing.", options: ["has studied", "studied", "has been studied", "had studied"], answer: 3, explain: "【答案解析】句意：我姐姐在去北京前已经在上海大学上了4年了。before后使用过去式，则主语动词应使用过去完成时态，故答案选D。" },
      { q: "By the time the teacher came, we ______ cleaning the classroom.", options: ["finished", "have finished", "had finished"], answer: 2, explain: "【答案解析】句意：等到老师来的时候，我们已经打扫完教室了。by the time+过去式是过去完成时标志，故动词是had done的形式，故选C。" },
      { q: "Gift shop had been ______ when we got there.", options: ["close", "to close", "closed"], answer: 2, explain: "【答案解析】句意：我们到那里时，礼品店已经关门了。close动词，关闭，to close动词不定式，closed形容词，关着的。分析题干可知when引导的从句用一般过去时，而主句用过去完成时，其结构为had done，结合题干中had been可知be动词后用形容词closed作表语。故选C。" },
      { q: "Alice ______ Changsha, so you can't see her here today.", options: ["has been to", "has gone to", "goes to", "went"], answer: 1, explain: "【答案解析】句意：爱丽丝去长沙了，所以你今天不能在这里见到她。has been to去过某地，人已经回来；has gone to去了某地，人还没有回来；goes to去某地，一般现在时；went去过，一般过去时。根据so you can't see her here today可知人没有回来，用has gone to，故答案为B。" },
      { q: "Chris ______ his seat belt before his father asked him to do so.", options: ["fastened", "fastens", "had fastened", "will fasten"], answer: 2, explain: "【答案解析】句意：克里斯在他父亲要求他系好安全带之前就已经系好了。fasten，使固定，动词；此处是before引导的时间状语从句，根据句意可知，此处表示过去某一时间或动作以前已经发生或完成了的动作，用过去完成时，用had done结构，故选C。" },
      { q: "I told my mother what ______ the girl.", options: ["was happened to", "happened", "happened on", "had happened to"], answer: 3, explain: "【答案解析】句意：我把那个女孩的事告诉了我母亲。发生在女孩身上的事情应该在告诉妈妈之前，所以要用过去完成时，要用had done形式表示，happen to sb. 发生在某人身上，是固定搭配，故选D。" },
      { q: "The plane ______ when we got to the airport.", options: ["is taking off", "had taken off", "has taken off", "will take off"], answer: 1, explain: "【答案解析】句意：当我们到达机场时，飞机已经起飞了。is taking off现在进行时；had taken off过去完成时；has taken off现在完成时；will take off一般将来时。根据when we got to the airport可知是当我到达机场时，飞机已经起飞了，是过去的过去，用过去完成时，故答案为B。" },
      { q: "Robert felt upset that most of his friends ______ when he ______ at the party.", options: ["left; had arrived", "had left; arrived", "left; arrived", "had left; had arrived"], answer: 1, explain: "【答案解析】句意：罗伯特感到不开心。当他到达晚会的时候，他大多数朋友都已经离开了。这是when连接的时间状语从句，从句为一般过去时，主句用过去完成时，表示主句动作发生在从句之前。故答案是B。" },
      { q: "Linda likes collecting stamps and by the end of last year she ______ about 2,000 stamps.", options: ["would collect", "was collecting", "has collected", "had collected"], answer: 3, explain: "【答案解析】句意：琳达喜欢集邮，到去年年底她已经收集了大约2000张邮票。would collect过去将来时；was collecting过去进行时；has collected现在完成时；had collected过去完成时。根据时间by the end of last year，可知动作是发生在过去的过去，用过去完成时，故答案为D。" },
      { q: "By the time I locked the door, I realized I ______ my key at home.", options: ["has left", "had left", "would left", "leave"], answer: 1, explain: "【答案解析】句意：当我锁门的时候，我意识到我把钥匙忘在家里了。has left现在完成时；had left过去完成时；would left过去将来时；leave一般现在时。根据句意和时间状语可知动作发生在\"过去的过去\"，用过去完成时，故答案为B。" },
      { q: "By the time I locked the door, I realized I ______ my keys at home.", options: ["has left", "have left", "had left", "was leaving"], answer: 2, explain: "【答案解析】句意：当我锁上门的时候，我意识到我把钥匙忘在家里了。has left现在完成时；have left现在完成时；had left过去完成时；was leaving过去进行时。根据By the time I locked the door和I realized，可知在我意识到之前我已经把钥匙忘在家里，表示过去的过去，时态用过去完成时，故答案选C。" },
      { q: "Sally knew she ______ the wrong dress as soon as she tried it on.", options: ["has bought", "had bought", "bought", "would buy"], answer: 1, explain: "【答案解析】句意：萨莉一试穿就知道她买错了衣服。A现在完成时；B过去完成时；C一般过去时；D过去将来时。根据主句的过去时可知从句应该用过去的某种时态，排除A；根据句意可知是已经发生了的动作造成的影响，应该用完成时态，故答案为B。" },
      { q: "When I looked at my phone, I realized I ______ through the alarm and was going to be late!", options: ["sleep", "will sleep", "have slept", "had slept"], answer: 3, explain: "【答案解析】句意：当我看手机时，我意识到我睡过了闹钟，要迟到了！睡过头发生在看手机之前，过去的过去要用过去完成时，要用had done表示过去完成时，故选D。" },
      { q: "By eight o'clock last night, we ______ over 20 pictures of the new library from Uncle Wang.", options: ["get", "got", "have got", "had got"], answer: 3, explain: "【答案解析】句意：到昨晚八点，我们从王叔叔那里得到了20多张新图书馆的照片。A get一般现在时；B got一般过去式；C have got现在完成时；D had got过去完成时。根据By eight o'clock last night，可知这个动作是在过去之前完成的，因此要用过去完成时，即had done形式，故选D。" },
      { q: "My father ______ when I hurried to the airport to see him off yesterday.", options: ["is leaving", "had left", "left", "will leave"], answer: 1, explain: "【答案解析】句意：昨天当我匆忙赶到机场给父亲送行时，他已经离开了。A现在进行时；B过去完成时；C一般过去时；D一般将来时。根据父亲离开发生在赶到机场之前和yesterday可知，此句是过去完成时，故选B。" },
      { q: "By the time my sisters ______ home yesterday, I ______ the dinner already.", options: ["reached; have cooked", "have reached; had cooked", "reached; had cooked"], answer: 2, explain: "【答案解析】句意：昨天等我的姐妹们到家的时候，我已经做好晚饭了。by the time...到...时候，引导时间状语从句，从句中有yesterday，应用一般过去时态reached；主句的动作在从句动作之前发生，应用过去完成时态had cooked。故选C。" },
      { q: "He said that he ______ to Canada a few years ago.", options: ["had been to", "have been to", "went", "go"], answer: 0, explain: "【答案解析】句意：他说他几年前去过加拿大。根据said，可知从句时态为过去时，排除B和D；根据句意可知是去过加拿大，已回，用完成时。综上，用过去完成时，故选A。" },
      { q: "—Why didn't you go to the movie with Rachel last night? —Oh, I ______ that movie twice.", options: ["have seen", "saw", "had seen"], answer: 2, explain: "【答案解析】句意：——昨晚你为什么不和Rachel去看电影？——哦，我已经看过两遍那部电影了。由答语可知在昨晚看电影前，我已经看过两遍这个电影了，事情发生在过去的过去，因此要用过去完成时，其结构为had+动词过去分词，故选C。" },
      { q: "The windows of our classroom ______. Do you know who did that?", options: ["break", "are broken", "will break", "were broken"], answer: 3, explain: "【答案解析】句意：我们教室的窗户被打破了。你知道是谁干的吗？根据后面的did，可知此处要用过去时态的被动语态were broken，故选D。" },
      { q: "The film ______ for five minutes when I got to the cinema.", options: ["had started", "had been on", "has been on"], answer: 1, explain: "【答案解析】句意：当我到达电影院时，电影已经开始五分钟了。根据for five minutes和got可知，此处表示过去的过去，用过去完成时，排除C；start是短暂性动词，而和时间状语for five minutes连用应该用延续性动词，所以用had been on。故选B。" },
      { q: "When I got to the subway station, all the underground entrances ______ for ten minutes.", options: ["has closed", "had been closed", "has been closed", "have closed"], answer: 1, explain: "【答案解析】句意：当我到达地铁站时，所有的地下入口已经关闭了十分钟。根据got和时间状语for ten minutes可知，此句用过去完成时，且close是短暂性动词，应该用had been closed。故选B。" },
      { q: "By the end of last month, I ______ all the CDs of Justin Bieber.", options: ["collect", "collected", "have collected", "had collected"], answer: 3, explain: "【答案解析】句意：到上个月末，我已经收集了Justin Bieber的所有的CD。根据By the end of last month可知，句子为过去完成时，过去完成时的结构为had+过去分词，故选D。" },
      { q: "—Lucy, did you catch the train to Wuhan yesterday? —No, It ______ for 10 minutes by the time I got to the station.", options: ["has left", "had left", "has been away", "had been away"], answer: 3, explain: "【答案解析】句意：——露西，你昨天赶上去武汉的火车了吗？——没有，我到车站的时候它已经走了10分钟了。火车离开的动作在我昨天到达火车站之前发生且已完成，因此句子的时态选择过去完成时；完成时态中表示一段时间的时间状语不能和瞬间动词连用，B选项中left为瞬间动词。故选D。" },
      { q: "We were late for the film last night. It ______ for 15 minutes when we arrived at the cinema.", options: ["had been on", "has been on", "has begun"], answer: 0, explain: "【答案解析】句意：昨晚看电影我们迟到了。当我们到达电影院的时候它都播映15分钟了。根据when we arrived at the cinema可知播映发生在过去的过去，应用过去完成时。故选A。" },
      { q: "By the end of last term, the students of Class One ______ three projects.", options: ["finished", "would finish", "have finished", "had finished"], answer: 3, explain: "【答案解析】句意：到上学期末，一班的学生已经完成了三个项目。根据by the end of last term，可知表示过去的过去，谓语动词要用过去完成时had+过去分词。故选D。" },
      { q: "Mary thought of the party which she ______ for this day.", options: ["plan", "planned", "had planned", "would plan"], answer: 2, explain: "【答案解析】句意：玛丽想起了她为今天计划的聚会。plan的动作发生在thought of的动作之前，表示过去的过去，要用过去完成时had+过去分词。故选C。" },
      { q: "I met Jim last week. We ______ each other for about twenty years since we left Japan.", options: ["didn't meet", "don't meet", "haven't met", "hadn't met"], answer: 3, explain: "【答案解析】句意：我上周见过吉姆。我们离开日本大约有二十年没见面了。for+时间段用完成时，排除A、B。met表明时态是过去时，所以用过去完成时hadn't met，故选D。" },
      { q: "—Did you catch the school bus this morning? —No. It ______ when I arrived at the bus stop.", options: ["is leaving", "has left", "had left", "would leave"], answer: 2, explain: "【答案解析】句意：——你今天早上赶上校车了吗？——没有，我到达车站时，车已经走了。根据Did you catch the school bus this morning?—No.可知当我到达汽车站时校车已经离开了。leave发生在arrived之前，表示过去的过去，因此用过去完成时。故选C。" },
      { q: "By the time he got up, he found his father ______ to work.", options: ["went", "have gone", "gone", "had gone"], answer: 3, explain: "【答案解析】句意：当他起床时，他发现他父亲已经去上班了。by the time到...时候为止，by+过去时间状语，经常和过去完成时连用，根据By the time he got up可知他父亲go to work是\"过去的过去\"，需用过去完成时，故选D。" },
      { q: "Daming ______ this pen for 5 years. He ______ it in 2014.", options: ["has bought; bought", "bought; bought", "has kept; has bought", "has had; bought"], answer: 3, explain: "【答案解析】句意：大明买这支笔已经五年了。他是在2014年买的。根据时间段for 5 years，可知第一空时态应为现在完成时，且动词为延续性含义，故排除AB。根据时间状语in 2014可知时态为一般过去时，故选D。" },
      { q: "Sue didn't go to see the film with us last week because she ______ it with her mother.", options: ["has seen", "had seen", "will see", "saw"], answer: 1, explain: "【答案解析】句意：苏上星期没和我们一起去看电影，因为她和她妈妈一起看过了。Sue和妈妈看了电影的影响是上周Sue没有和我们看电影，所以用完成时，根据didn't可知是与过去有关，所以用过去完成时，结构是had+动词过去分词，see的过去分词是seen，故选B。" },
      { q: "By the end of last month, I ______ all the CDs of Justin Bieber.", options: ["had collected", "collected", "have collected", "collect"], answer: 0, explain: "【答案解析】句意：到上个月底，我已经把贾斯汀·比伯的所有CD都收集到了。根据By the end of last month可知时态是过去完成时，结构是had+动词过去分词，collect的过去分词是collected，故选A。" },
      { q: "Before you came, I ______ just ordered dinner on the phone.", options: ["has", "had", "have", "was"], answer: 1, explain: "【答案解析】句意：你来之前，我刚在电话里订了晚餐。came来，时态是一般过去时，before在...之前，在一般过去时之前，所以用过去完成时，结构是had+动词过去分词，故选B。" },
      { q: "Her sister ______ in that school for two years before she went there as well.", options: ["has studied", "was studying", "has been studying", "had studied"], answer: 3, explain: "【答案解析】句意：她妹妹去那里之前也在那所学校学习过。went there使用的是过去时，去之前发生的动作是过去的过去，所以使用过去完成时，故答案是D。" },
      { q: "Some students of Class Five ______ the project by the end of last year.", options: ["had finished", "have finished", "will finish", "finished"], answer: 0, explain: "【答案解析】句意：五班的一些同学在去年末已经完成项目了。by the end of+时间，与完成时态连用，last year是过去的时间因此应使用过去完成时态had done形式，故选A。" },
      { q: "I ______ eaten the cupcake before you told me that it was for your sister.", options: ["had already", "have already", "already", "would have"], answer: 0, explain: "【答案解析】句意：在你告诉我那是给你妹妹吃的之前，我已经吃过了这个纸杯蛋糕。before在...之前，told告诉，一般过去时，发生在过去的事情之前，所以用过去完成时，结构是had+动词过去分词，故选A。" },
      { q: "When I got up early the next morning, John and his wife ______ to work.", options: ["went", "has gone", "have gone", "had gone"], answer: 3, explain: "【答案解析】句意：第二天一早我起床时，约翰和他的妻子已经去上班了。我起床时约翰和妻子已经去上班了，所以用完成时，got表明时态是一般过去时，发生在过去的过去，所以用过去完成时，结构是had+动词过去分词，故选D。" }
    ]
  },
  t_all: {
    icon: "📝",
    intro: "全部时态专项练习：综合检测初中阶段8种核心时态，共100道精选选择题，涵盖一般现在时、现在进行时、一般过去时、过去进行时、一般将来时、过去将来时、现在完成时、过去完成时。",
    questions: [
    { q: "I will tell him as soon as he ______ back.", options: ["come", "comes", "will come", "came"], answer: 1, explain: "as soon as 引导时间状语从句，主将从现：主句用 will tell，从句用一般现在时。he 是第三人称单数，come 加 -s 变 comes。" },
      { q: "Mary ______ on shoes when she ______ them.", options: ["tries …buys", "tries …buies", "trys …buys", "trys …buies"], answer: 0, explain: "一般现在时表示习惯性动作。try→tries（辅音字母+y结尾变y为i加es），buy→buys（元音字母+y结尾直接加s）。" },
      { q: "The girl often ______ cold when she ______.", options: ["cathcs … dances", "catches … dances", "catchs … dancees", "catches … dancee"], answer: 1, explain: "一般现在时。catch→catches（以ch结尾加es），dance→dances（以e结尾直接加s）。often表示经常性动作。" },
      { q: "______ he ______ himself there? No, I don't think so.", options: ["Do …enjoy", "Does …enjoies", "Does …enjoys", "Does …enjoy"], answer: 3, explain: "he是第三人称单数，疑问句用Does提问，后接动词原形enjoy。Does后动词用原形，不加s。" },
      { q: "______ your teacher ______ from them very often? Certainly.", options: ["Do …hear", "Does …hear", "Do …receive", "receive"], answer: 1, explain: "your teacher是第三人称单数，用Does提问，后接动词原形hear。hear from=收到来信。" },
      { q: "______ your mother ______ some cleaning on Sundays?", options: ["Does …does", "Do …does", "Does …do", "Do … do"], answer: 2, explain: "your mother是第三人称单数，用Does提问，后接动词原形do。Does后动词用原形do，不是does。" },
      { q: "______ Tom ______ to work hard to help his family? Yes, he ______.", options: ["Has …x …does", "Has …x…does", "Does …has…has", "Does … have …does"], answer: 3, explain: "have to表示'必须'，疑问句用Does提问后接原形have。简短回答用does。Does Tom have to...? Yes, he does." },
      { q: "Which teacher ______ lessons to you every day?", options: ["does … gives", "does … give", "do … give", "gives"], answer: 3, explain: "Which teacher是单数主语，every day表示一般现在时，谓语用第三人称单数gives。主语为疑问词时不需助动词。" },
      { q: "Smith does not go fishing on weekdays, ______? ______, he does.", options: ["does he … No", "does he … Yes", "doesn't he … No", "doesn't he … Yes"], answer: 0, explain: "前否定（does not）后肯定（does he?）。否定陈述句→肯定反意疑问。回答No, he doesn't（确认否定）。" },
      { q: "Mr Black often ______ fishing on Sundays, ______ he?", options: ["goes … doesn't", "goes … isn't", "doesn't go … does", "doesn't go … is"], answer: 0, explain: "often表示一般现在时，go→goes（以es结尾加es）。前肯定后否定：goes→doesn't he?" },
      { q: "He usually ______ TV on Sunday evening.", options: ["watch", "watches", "watching", "is watching"], answer: 1, explain: "usually表示一般现在时，he是第三人称单数，watch→watches（以ch结尾加es）。" },
      { q: "We'll go to play with snow if it ______ tomorrow.", options: ["snow", "snows", "will snow", "snowed"], answer: 1, explain: "if引导条件状语从句，主将从现：主句用will go，从句用一般现在时。it是第三人称单数，snow→snows。" },
      { q: "Neither I nor he ______ French.", options: ["speak", "doesn't speak", "speaks", "doesn't speak"], answer: 2, explain: "neither...nor...就近原则：he是第三人称单数，用speaks。speak→speaks（加s）。" },
      { q: "Nobody ______ how to run this machines.", options: ["know", "have known", "knows", "is knowing"], answer: 2, explain: "nobody作主语视为第三人称单数，用knows。know→knows（加s）。" },
      { q: "The Young Pioneer ______ water for the old man every day.", options: ["carry", "bring", "takes", "carries"], answer: 3, explain: "The Young Pioneer是单数主语，every day表示一般现在时。carry→carries（辅音字母+y结尾变y为i加es）。" },
      { q: "Some are ______ in the river and some are ______ games.", options: ["swimming …playing", "swimming …plaiing", "swimming …I playing", "swimming …plaing"], answer: 0, explain: "现在进行时：are swimming, are playing。swim→swimming（双写m加ing），play→playing（直接加ing）。" },
      { q: "Look! The boy students are ______ football while the girls are ______.", options: ["playing … dance", "playing … dancing", "play … dancing", "play … dance"], answer: 1, explain: "Look!表示现在进行时。are playing, are dancing。dance→dancing（去e加ing）。" },
      { q: "He ______ to do his lessons at eight every evening.", options: ["is beginning", "is beginning", "begin", "begins"], answer: 3, explain: "every evening表示一般现在时，he是第三人称单数，begin→begins。" },
      { q: "______ he ______ on well with his friends this term?", options: ["Does …gets", "Does …get", "Is …getting", "Is …geting"], answer: 2, explain: "this term表示当前正在进行，用现在进行时Is...getting。get on well with=与...相处融洽。get→getting（双写t加ing）。" },
      { q: "Mr Smith ______ short stories, but he ______ a TV play these days.", options: ["is writing …is writing", "is writing … writes", "writes …is writing", "writes …writes"], answer: 2, explain: "写短篇故事是习惯（一般现在时writes），these days表示当前正在进行（现在进行时is writing）。" },
      { q: "I ______ to the cinema. I ______ there every Sunday.", options: ["go…go", "am going …go", "go…am going", "am going …am going"], answer: 1, explain: "第一空表示即将去用am going（现在进行时表将来），第二空every Sunday表示习惯用go（一般现在时）。" },
      { q: "Look, they ______ a good time, ______ they?", options: ["have …do", "have …don't", "are having …are", "are having …aren't"], answer: 3, explain: "Look!表示现在进行时are having。前肯定后否定：are having→aren't they?" },
      { q: "You ______ about the future now, ______ you?", options: ["don't think …don't", "aren't thinking …aren't", "don't think … do", "aren't thinking … are"], answer: 1, explain: "now表示现在进行时aren't thinking。前否定后肯定... 实际上aren't是否定，所以反意疑问用肯定are。" },
      { q: "She always ______ something whenever she ______.", options: ["studied …played", "studied …plaied", "studied …plaied", "studied …played"], answer: 3, explain: "whenever引导，用一般过去时。study→studied（变y为i加ed），play→played（直接加ed）。" },
      { q: "He often ______ late in the forest. It ______ me very much.", options: ["stayed … worried", "staied … worried", "stayed … worryed", "staied … worried"], answer: 0, explain: "一般过去时。stay→stayed（直接加ed），worry→worried（变y为i加ed）。" },
      { q: "I ______ that the boy ______ with no tears in his eyes.", options: ["noticed … cryed", "noticed … cried", "noticed … cried", "noticed … cryed"], answer: 1, explain: "一般过去时。notice→noticed（直接加ed），cry→cried（变y为i加ed）。" },
      { q: "We ______ the floor and ______ all the windows.", options: ["mopped …cleanned", "moped …cleaned", "mopped …cleaned", "moped …cleaned"], answer: 2, explain: "一般过去时。mop→mopped（重读闭音节双写p加ed），clean→cleaned（直接加ed）。" },
      { q: "When I ______ the Children's Palace, the children ______ with joy.", options: ["visited … jumpped", "visited … jumped", "visited …jumped", "visited …jumpped"], answer: 1, explain: "一般过去时。visit→visited（直接加ed），jump→jumped（直接加ed，不是jumpped）。" },
      { q: "______ a sports meet last Sunday? Yes, they ______.", options: ["Did they have … did", "Did they have … had", "Had they … had", "Had they … did"], answer: 0, explain: "last Sunday用过去时。Did...have? Yes, they did.（Did后接原形have，简短回答用did）。" },
      { q: "______ you ______ out for a walk after supper? Yes, I ______.", options: ["Did …went …went", "Did …go …went", "Did …went …did", "Did …go …did"], answer: 3, explain: "Did后接动词原形go。简短回答用did。Did you go...? Yes, I did." },
      { q: "______ Jack ______ on with his work or ______ to have a rest?", options: ["Did …went …stopped", "Did …go …stop", "Did …went …stop", "Did …go …stopped"], answer: 1, explain: "Did后接动词原形go和stop。选择疑问句：Did Jack go on or stop to...?" },
      { q: "You gave them a talk two days ago, ______ you? Yes, I ______.", options: ["did …did", "did …gave", "didn't …did", "didn't …gave"], answer: 2, explain: "gave是肯定→反意疑问用否定didn't you?。肯定回答Yes, I did。" },
      { q: "______ your brother ______ a letter to? My father.", options: ["Who…wrote", "What …wrote", "Who did …write", "What did …write"], answer: 2, explain: "对人提问用Who。疑问句用did后接动词原形write。Who did your brother write a letter to?" },
      { q: "They ______ about the TV news then in the sitting-room. They often ______ such talks.", options: ["talked … had", "talk … have", "were talking … had", "are talking … have"], answer: 2, explain: "then=当时→过去进行时were talking。often在过去语境中表示过去习惯→had。" },
      { q: "He ______ some cooking at that time, so ______ me.", options: ["did … heard", "did … didn't hear", "was doing …heard", "was doing … didn't hear"], answer: 3, explain: "at that time→过去进行时was doing。so（所以）他没听到→didn't hear（一般过去时）。" },
      { q: "\"______ you angry then?\" \"They ______ too much noise.\"", options: ["Are … were making", "Were … were making", "Are …made", "Were…made"], answer: 1, explain: "then→过去时。Were you angry? making too much noise→过去进行时were making。" },
      { q: "This time yesterday Jack ______ his bike. He ______ TV.", options: ["repaired … didn't watch", "was repairing … watched", "repaired … watched", "was repairing … wasn't watching"], answer: 3, explain: "this time yesterday→过去进行时。was repairing，wasn't watching。两个动作同时在进行。" },
      { q: "We ______ for Tom at ten last Sunday. He often kept us ______.", options: ["were waiting …waiting", "were waiting …wait", "waited …waiting", "waited …wait"], answer: 0, explain: "at ten last Sunday→过去进行时were waiting。keep sb. doing是固定搭配→kept us waiting。" },
      { q: "When you ______ at the door, I ______ some washing.", options: ["knocked … did", "was knocking … did", "knocked …was doing", "knock …am doing"], answer: 2, explain: "When从句用一般过去时knocked（突发动作），主句用过去进行时was doing（背景动作）。" },
      { q: "The boy ______ English on the radio when I ______ his door.", options: ["learned … was opening", "was learning … opened", "learned … opened", "is learning … open"], answer: 1, explain: "when从句用一般过去时opened（突发动作），主句用过去进行时was learning（背景动作）。" },
      { q: "When they ______ through the forest, a bear ______ at them.", options: ["walked … was coming", "were walking … came", "were talking … comes", "walk … is coming"], answer: 1, explain: "When从句用过去进行时were walking（背景），主句用一般过去时came（突发动作）。" },
      { q: "A young man ______ her while she ______ her work.", options: ["watched … was finishing", "was watching … finished", "watched …finished", "was watching …was finishing"], answer: 3, explain: "while引导两个同时进行的过去动作，都用过去进行时：was watching和was finishing。" },
      { q: "While mother ______ some washing, I ______ a kite for Kack.", options: ["did …made", "was doing …made", "was doing …was making", "did …was making"], answer: 1, explain: "while从句用过去进行时was doing（背景），主句用一般过去时made（完成的动作）。" },
      { q: "I ______ myself French from 7 to 9 yesterday morning. I ______ to work.", options: ["was teaching … didn't go", "taught … didn't go", "was teaching … went", "taught … went"], answer: 0, explain: "from 7 to 9 yesterday morning→过去进行时was teaching。didn't go to work（一般过去时否定）。" },
      { q: "He ______ a model plane when I came to see him.", options: ["makes", "is making", "was making", "made"], answer: 2, explain: "when I came→过去时间点，用过去进行时was making。" },
      { q: "I ______ a letter at nine last night.", options: ["is writing", "was writing", "wrote", "is writing"], answer: 1, explain: "at nine last night→过去时间点，用过去进行时was writing。" },
      { q: "The teacher ______ (give) us a history lesson when Tom walked into the classroom.", options: ["gave", "is giving", "was given", "was giving"], answer: 3, explain: "when Tom walked into→过去时间点，主句用过去进行时was giving。" },
      { q: "There will be a football match in two days, that is ______.", options: ["last Sunday", "next Sunday", "every Sunday", "this Sunday"], answer: 1, explain: "in two days=两天后表示将来。next Sunday是将来时间。" },
      { q: "We ______ class meeting this November.", options: ["had", "have", "will have", "are having"], answer: 2, explain: "this November表示将来，用will have。" },
      { q: "He ______ in his garden every morning next year.", options: ["will work", "works", "worked", "is working"], answer: 0, explain: "next year表示将来，用will work表示将来的习惯。" },
      { q: "Be careful. The train ______.", options: ["will come", "is going to come", "comes", "is coming"], answer: 3, explain: "Be careful表示紧迫，火车即将到达。用现在进行时is coming表即将发生。" },
      { q: "Look at those clouds. It ______ soon, I'm afraid.", options: ["is going to rain", "is raining", "will rain", "won't rain"], answer: 0, explain: "Look at those clouds提供了天气迹象，用be going to rain表示根据迹象推测。" },
      { q: "The radio says it ______ the day after tomorrow.", options: ["is going to snow", "is snowing", "will snow", "snows"], answer: 2, explain: "The radio says表示天气预报，the day after tomorrow表示将来，用will snow。" },
      { q: "______ he ______ some shopping tomorrow afternoon?", options: ["Will …does", "is going to do", "is …doing", "Shall …do"], answer: 1, explain: "tomorrow afternoon表示将来。用Is he going to do...? be going to+动词原形。" },
      { q: "What day ______ it ______ tomorrow? Wednesday.", options: ["is …going to be", "will …be", "shall …be", "does …be"], answer: 1, explain: "tomorrow表示将来，用What day will it be...? will+be动词原形。" },
      { q: "The boy ______ sixteen years old next year.", options: ["is going to be", "is growing to be", "will be", "is"], answer: 2, explain: "next year表示将来，年龄用will be。" },
      { q: "______ you ______ me up at six, please?", options: ["Are …going to wake", "Are …waking", "Will …wake", "Do …wake"], answer: 2, explain: "please表示请求，用Will you wake...? Will用于礼貌请求。" },
      { q: "If he ______ to college, he ______ a lot more.", options: ["will go …will learn", "will go …is going to learn", "is going … is going to learn", "goes … will learn"], answer: 3, explain: "if引导条件状语从句，主将从现：从句用goes（第三人称单数），主句用will learn。" },
      { q: "When she ______ next time, I ______ her everything.", options: ["is going to come …shall tell", "will come …shall tell", "comes …will tell", "come …will tell"], answer: 2, explain: "When引导时间状语从句，主将从现：从句用comes（第三人称单数），主句用will tell。" },
      { q: "What day ______ it ______ tomorrow? It ______ Tuesday.", options: ["is …going to be …is", "will …be …will", "is …going to be …is going", "will be …will be"], answer: 1, explain: "tomorrow表示将来。What day will it be? It will be Tuesday. will+be动词原形。" },
      { q: "She ______ that she ______ her best to help them the next term.", options: ["says … will do", "said … will do", "said … would do", "says … would do"], answer: 2, explain: "said是过去时，the next term表示过去将来，用would do。主句过去时→从句过去将来时。" },
      { q: "People ______ that the Smiths ______ for a holiday next week.", options: ["say … will go", "said … will go", "said … would go", "say … would go"], answer: 0, explain: "People say是现在时，next week表示将来，用will go。主句现在时→从句将来时。" },
      { q: "Nobody ______ us that he ______ even stricter with us.", options: ["tell … will be", "tells … would be", "told … will be", "told … would be"], answer: 3, explain: "told是过去时，用过去将来时would be。主句过去时→从句过去将来时。" },
      { q: "Please ______ him that we ______ able to help him.", options: ["tell … will be", "tells … would be", "told … will be", "told … would be"], answer: 0, explain: "Please tell是祈使语气（现在时），we will be是将来时。主句现在时→从句将来时。" },
      { q: "Jack ______ that they ______ surprised to see it this Friday.", options: ["know … would be", "knows … will be", "knew … would be", "knew … will be"], answer: 2, explain: "knew是过去时，用过去将来时would be。主句过去时→从句过去将来时。" },
      { q: "I ______ to know if Mary ______ by train that afternoon.", options: ["want … would go", "want … will go", "wanted … would go", "wanted … will go"], answer: 2, explain: "wanted是过去时，that afternoon表示过去将来，用would go。if引导宾语从句中用过去将来时。" },
      { q: "______ he ______ that they ______ home tomorrow?", options: ["Does …learn … would go", "Does …learn … will go", "Did … learn … would go", "Did … learn … will go"], answer: 2, explain: "Did he learn是过去时，tomorrow从过去看是将来的事，用would go。主句过去时→从句过去将来时。" },
      { q: "We ______ that they ______ a sports meet tomorrow.", options: ["learn … would have", "have learned … would have", "learn … will have", "have learned … will have"], answer: 2, explain: "We learn是现在时，tomorrow表示将来，用will have。主句现在时→从句将来时。" },
      { q: "______ you ______ that he ______ his lost son one day?", options: ["Do … think … will find", "Do … thought … would find", "Did … think … will find", "Did … thought … would find"], answer: 3, explain: "Did you think是过去时，one day表示将来（从过去看），用would find。主句过去时→从句过去将来时。" },
      { q: "I ______ that you ______ good care of her that day.", options: ["thought …will take", "thought …would take", "think …will take", "think …would take"], answer: 1, explain: "thought是过去时，that day表示过去将来，用would take。主句过去时→从句过去将来时。" },
      { q: "The visitors ______ where they ______ a short test.", options: ["ask … would take", "ask … will take", "asked … would take", "asked … can take"], answer: 2, explain: "asked是过去时，用过去将来时would take。主句过去时→从句过去将来时。" },
      { q: "John ______ sure that he ______ good at chemistry soon.", options: ["be … will be", "is, would be", "was … will be", "was … would be"], answer: 3, explain: "was是过去时，soon表示将来（从过去看），用would be。主句过去时→从句过去将来时。" },
      { q: "She ______ ill so she ______ able to go skating the next day.", options: ["is … won't be", "is … wouldn't be", "was … won't be", "was … wouldn't be"], answer: 3, explain: "was是过去时，the next day表示过去将来，用wouldn't be。主句过去时→从句过去将来时。" },
      { q: "He ______ the thief to the police when he ______ the man again.", options: ["would take …would meet", "would take …met", "will take … will meet", "will take … meet"], answer: 3, explain: "when引导时间状语从句，主将从现：主句用will take（将来），从句用meets（现在时代替将来）。" },
      { q: "Mother ______ me a new coat yesterday, I ______ it on. It fits me well.", options: ["has made …have tried", "made … have tried", "has made …tried", "made …tried"], answer: 1, explain: "yesterday用made（过去时），现在试穿过用have tried（现在完成时），It fits me well（现在时说明结果）。" },
      { q: "\"He ______ to draw horses already.\" \"When ______ he?\" \"Last year.\"", options: ["learned …has", "learned …did", "has learned …has", "has learned …did"], answer: 3, explain: "already用现在完成时has learned，When did he?用did（过去时疑问），Last year表示过去。" },
      { q: "Tom ______ up into the tree. Look, he ______ high up there!", options: ["has got … is", "has climbed … was", "got … was", "climbed … is"], answer: 0, explain: "has got up（现在完成时，已爬上去），Look! he is high up there（现在时状态）。" },
      { q: "______ you ______ the text yet? Yes, we ______ it two hours ago.", options: ["Did …copy …did", "Have …copied …have", "Have … copied … did", "Did …copy …had"], answer: 2, explain: "yet用现在完成时Have copied，two hours ago用过去时did。Did后接原形，简短回答用did。" },
      { q: "\"Why ______ she ______ angry?\" \"Because he ______ at her just now.\"", options: ["did …get …shouted", "has …got …shouted", "did …get …has shouted", "has …got …has shouted"], answer: 1, explain: "has got angry（现在完成时，当前状态），shouted just now（一般过去时，原因）。just now=刚才用过去时。" },
      { q: "______ you ______ the film before? Where ______ you ______ it?", options: ["Have …seen …did …see", "Did …see …did …watch", "Have …seen … have … seen", "Did …see …have …seen"], answer: 0, explain: "before用现在完成时Have seen，Where did you see it?用过去时did see。" },
      { q: "You ______ me waiting for two hours. I ______ for you since five.", options: ["kept …waited", "have kept …waited", "kept …have waited", "have kept …have waited"], answer: 3, explain: "for two hours和since five都表示到现在为止，用现在完成时have kept和have waited。" },
      { q: "Where ______ John ______? To the library. He ______ there for an hour.", options: ["has …been …has gone", "has …gone …has been", "did …go …went", "did …be …went"], answer: 1, explain: "Where has John gone?（去了哪，has gone表去了未回）。He has been there for an hour（在那里待了，has been表状态持续）。" },
      { q: "______ the baby still ______? No, it ______ crying.", options: ["Has …cried …has stopped", "Is …crying …stopped", "Did …cry …stopped", "Is …crying …has stopped"], answer: 3, explain: "Is the baby still crying?（现在进行时），No, it has stopped crying（现在完成时，已停止）。" },
      { q: "I ______ the way. I ______ here for quite many years.", options: ["knew … have lived", "knew … live", "know …have lived", "know …live"], answer: 2, explain: "I know the way（现在时），I have lived here for quite many years（现在完成时，for+时间段）。" },
      { q: "______ you ever ______ America? Yes, I have.", options: ["Have … gone to", "Have … gone in", "Have …been to", "Have …been in"], answer: 2, explain: "Have you ever been to America?（去过已回来，been to表去过已回）。gone to表去了未回。" },
      { q: "My brother ______ college for over three years.", options: ["has gone to", "has been to", "has been in", "has been for"], answer: 2, explain: "has been in college（在大学待了三年多，been in表持续状态）。for over three years+现在完成时。" },
      { q: "He ______ the Army by the end of 1992. He ______ in the army since then.", options: ["joined … is", "has joined … has been", "had joined … is", "had joined … has been"], answer: 3, explain: "by the end of 1992用过去完成时had joined，since then用现在完成时has been。" },
      { q: "By the time I ______ back they ______ up ten metres.", options: ["came …have climbed", "came …had climbed", "come …have climbed", "had come …climbed"], answer: 1, explain: "By the time I came（过去时），they had climbed（过去完成时，在came之前完成）。" },
      { q: "Jack ______ over five lessons by seven o'clock. Then he ______ a test.", options: ["went …took", "went …had taken", "had gone …took", "had gone …had taken"], answer: 2, explain: "by seven o'clock用过去完成时had gone over（复习），Then he took a test（一般过去时）。" },
      { q: "We ______ out by that time that he ______ a thief for a long time.", options: ["had found …had been", "had found …was", "found …had been", "found …was"], answer: 0, explain: "by that time用过去完成时had found out，for a long time也用过去完成时had been。" },
      { q: "Before the news ______ him, he ______ to know about it.", options: ["reaches …has got", "reached …had got", "reached …got", "had reached …got"], answer: 1, explain: "Before the news reached him（过去时），he had got to know（过去完成时，在reached之前已知道）。" },
      { q: "I ______ him a second letter before I ______ from him.", options: ["wrote … heard", "wrote … had heard", "had written … heard", "have written … hear"], answer: 2, explain: "before I heard from him（过去时），I had written（过去完成时，在heard之前完成）。" },
      { q: "We ______ in a good harvest because we ______ enough rain.", options: ["didn't get …had had", "got …had had", "had got …had had", "got … hadn't had"], answer: 1, explain: "We got in a good harvest（一般过去时），because we had had enough rain（过去完成时，在收获之前有足够雨水）。" },
      { q: "They ______ for five hours when they ______ in New York.", options: ["flew … arrived", "had flown … had arrived", "flew … had arrived", "had flown … arrived"], answer: 3, explain: "for five hours（持续到到达之前）用过去完成时had flown，when they arrived（一般过去时）。" },
      { q: "She ______ that it ______ for two days by that day.", options: ["says … has rained", "says … had rained", "said … had rained", "said … rained"], answer: 2, explain: "She said（过去时），for two days by that day用过去完成时had rained（到那天为止已下了两天）。" },
      { q: "John ______ there since the year before, so he ______ them.", options: ["had worked …knew", "had worked …had known", "worked … knew", "worked … had known"], answer: 0, explain: "since the year before用过去完成时had worked，so he knew them（一般过去时，知道他们）。" },
      { q: "He ______ angry because he ______ for a long time.", options: ["had got …had waited", "got …waited", "had got …waited", "got … had waited"], answer: 3, explain: "He got angry（一般过去时），because he had waited for a long time（过去完成时，在got angry之前等了很久）。" },
      { q: "Paper ______ first invented in China.", options: ["is", "are", "was", "were"], answer: 2, explain: "Paper是不可数名词（单数），first invented是被动语态，用一般过去时was invented。" },
      { q: "The Greens ______ China for five years.", options: ["has been in", "have been in", "went to", "has gone to"], answer: 1, explain: "The Greens是复数（格林一家），for five years用现在完成时have been in（在...待了五年）。" },
      { q: "There ______ an eraser under the desk. Is it yours?", options: ["is", "has", "was", "had"], answer: 0, explain: "There is an eraser（现在时，表示存在）。Is it yours?（现在时）说明当前状态。" }

    ]
  }
};

